INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000001,'challenges','{"id":760300000000001,"title":"A1 · Разговорный · Знакомство и этикет · Challenge 1","description":"A1: знакомство и этикет. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"A1","icon":"⚡","xp":29,"category":"Знакомство и этикет","track":"Разговорный","topic":"Знакомство и этикет","duration":"7 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «excuse me».","options":["увидимся позже","приятно познакомиться","доброе утро","извините"],"correctAnswer":"извините","explanation":"«excuse me» — «извините»."},{"id":2,"question":"Какое выражение на британском английском соответствует «приятно познакомиться»?","options":["see you later","I am sorry","nice to meet you","how are you?"],"correctAnswer":"nice to meet you","explanation":"«nice to meet you» — «приятно познакомиться»."},{"id":3,"question":"Выбери точное русское значение выражения «good evening».","options":["увидимся позже","добрый вечер","меня зовут","приятно познакомиться"],"correctAnswer":"добрый вечер","explanation":"«good evening» — «добрый вечер»."},{"id":4,"question":"Выбери точное русское значение выражения «my name is».","options":["пожалуйста","привет","меня зовут","как дела?"],"correctAnswer":"меня зовут","explanation":"«my name is» — «меня зовут»."},{"id":5,"question":"Какое выражение на британском английском соответствует «пожалуйста»?","options":["hello","see you later","good morning","please"],"correctAnswer":"please","explanation":"«please» — «пожалуйста»."},{"id":6,"question":"Выбери точное русское значение выражения «good morning».","options":["как дела?","меня зовут","доброе утро","приятно познакомиться"],"correctAnswer":"доброе утро","explanation":"«good morning» — «доброе утро»."},{"id":7,"question":"Выбери точное русское значение выражения «could you help me?».","options":["приятно познакомиться","не могли бы вы мне помочь?","извините","меня зовут"],"correctAnswer":"не могли бы вы мне помочь?","explanation":"«could you help me?» — «не могли бы вы мне помочь?»."},{"id":8,"question":"Какое выражение на британском английском соответствует «спасибо»?","options":["see you later","nice to meet you","thank you","how are you?"],"correctAnswer":"thank you","explanation":"«thank you» — «спасибо»."}],"durationMinutes":7,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 29 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000002,'challenges','{"id":760300000000002,"title":"A2 · Разговорный · Знакомство и этикет · Challenge 2","description":"A2: знакомство и этикет. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"A2","icon":"⚡","xp":31,"category":"Знакомство и этикет","track":"Разговорный","topic":"Знакомство и этикет","duration":"8 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «take your time».","options":["я ищу","не торопись","я не уверен","это зависит от обстоятельств"],"correctAnswer":"не торопись","explanation":"«take your time» — «не торопись»."},{"id":2,"question":"Какое выражение на британском английском соответствует «дай мне знать»?","options":["let me know","I am looking for","I would like","I disagree"],"correctAnswer":"let me know","explanation":"«let me know» — «дай мне знать»."},{"id":3,"question":"Выбери точное русское значение выражения «could I have».","options":["я ищу","дай мне знать","не торопись","можно мне"],"correctAnswer":"можно мне","explanation":"«could I have» — «можно мне»."},{"id":4,"question":"Выбери точное русское значение выражения «by the way».","options":["я ищу","я бы хотел","кстати","не торопись"],"correctAnswer":"кстати","explanation":"«by the way» — «кстати»."},{"id":5,"question":"Какое выражение на британском английском соответствует «я согласен»?","options":["let me know","I disagree","I agree","shall we start?"],"correctAnswer":"I agree","explanation":"«I agree» — «я согласен»."},{"id":6,"question":"Выбери точное русское значение выражения «I am looking for».","options":["я не согласен","кстати","я ищу","это зависит от обстоятельств"],"correctAnswer":"я ищу","explanation":"«I am looking for» — «я ищу»."},{"id":7,"question":"Выбери точное русское значение выражения «I am not sure».","options":["я ищу","я не уверен","кстати","начнём?"],"correctAnswer":"я не уверен","explanation":"«I am not sure» — «я не уверен»."},{"id":8,"question":"Какое выражение на британском английском соответствует «что ты думаешь?»?","options":["by the way","let me know","could I have","what do you think?"],"correctAnswer":"what do you think?","explanation":"«what do you think?» — «что ты думаешь?»."}],"durationMinutes":8,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 31 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000003,'challenges','{"id":760300000000003,"title":"B1 · Разговорный · Знакомство и этикет · Challenge 3","description":"B1: знакомство и этикет. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B1","icon":"⚡","xp":36,"category":"Знакомство и этикет","track":"Разговорный","topic":"Знакомство и этикет","duration":"9 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «I see your point».","options":["с другой стороны","насколько мне известно","достичь соглашения","я понимаю твою точку зрения"],"correctAnswer":"я понимаю твою точку зрения","explanation":"«I see your point» — «я понимаю твою точку зрения»."},{"id":2,"question":"Какое выражение на британском английском соответствует «насколько мне известно»?","options":["reach an agreement","on the other hand","in my opinion","as far as I know"],"correctAnswer":"as far as I know","explanation":"«as far as I know» — «насколько мне известно»."},{"id":3,"question":"Выбери точное русское значение выражения «look forward to».","options":["насколько мне известно","по моему мнению","с нетерпением ждать","прояснить недоразумение"],"correctAnswer":"с нетерпением ждать","explanation":"«look forward to» — «с нетерпением ждать»."},{"id":4,"question":"Выбери точное русское значение выражения «on the other hand».","options":["с другой стороны","принимать участие в","с нетерпением ждать","предложить идею"],"correctAnswer":"с другой стороны","explanation":"«on the other hand» — «с другой стороны»."},{"id":5,"question":"Какое выражение на британском английском соответствует «достичь соглашения»?","options":["in my opinion","keep in touch","take part in","reach an agreement"],"correctAnswer":"reach an agreement","explanation":"«reach an agreement» — «достичь соглашения»."},{"id":6,"question":"Выбери точное русское значение выражения «that sounds reasonable».","options":["если честно","это звучит разумно","принимать участие в","с нетерпением ждать"],"correctAnswer":"это звучит разумно","explanation":"«that sounds reasonable» — «это звучит разумно»."},{"id":7,"question":"Выбери точное русское значение выражения «keep in touch».","options":["поддерживать связь","прояснить недоразумение","если честно","с другой стороны"],"correctAnswer":"поддерживать связь","explanation":"«keep in touch» — «поддерживать связь»."},{"id":8,"question":"Какое выражение на британском английском соответствует «прояснить недоразумение»?","options":["clear up a misunderstanding","as far as I know","on the other hand","in my opinion"],"correctAnswer":"clear up a misunderstanding","explanation":"«clear up a misunderstanding» — «прояснить недоразумение»."}],"durationMinutes":9,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 36 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000004,'challenges','{"id":760300000000004,"title":"B2 · Разговорный · Знакомство и этикет · Challenge 4","description":"B2: знакомство и этикет. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B2","icon":"⚡","xp":41,"category":"Знакомство и этикет","track":"Разговорный","topic":"Знакомство и этикет","duration":"10 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «have mixed feelings».","options":["испытывать смешанные чувства","привести веский аргумент","прояснить предположение","выразить иначе"],"correctAnswer":"испытывать смешанные чувства","explanation":"«have mixed feelings» — «испытывать смешанные чувства»."},{"id":2,"question":"Какое выражение на британском английском соответствует «разобраться с недопониманием»?","options":["take into account","weigh up the options","express a reservation","address a misunderstanding"],"correctAnswer":"address a misunderstanding","explanation":"«address a misunderstanding» — «разобраться с недопониманием»."},{"id":3,"question":"Выбери точное русское значение выражения «put it another way».","options":["выразить сомнение","прояснить предположение","испытывать смешанные чувства","выразить иначе"],"correctAnswer":"выразить иначе","explanation":"«put it another way» — «выразить иначе»."},{"id":4,"question":"Выбери точное русское значение выражения «clarify an assumption».","options":["прояснить предположение","выразить сомнение","выразить обеспокоенность","разобраться с недопониманием"],"correctAnswer":"прояснить предположение","explanation":"«clarify an assumption» — «прояснить предположение»."},{"id":5,"question":"Какое выражение на британском английском соответствует «прийти к выводу»?","options":["come to a conclusion","address a misunderstanding","make a valid point","take into account"],"correctAnswer":"come to a conclusion","explanation":"«come to a conclusion» — «прийти к выводу»."},{"id":6,"question":"Выбери точное русское значение выражения «strike a balance».","options":["прояснить предположение","испытывать смешанные чувства","привести веский аргумент","найти баланс"],"correctAnswer":"найти баланс","explanation":"«strike a balance» — «найти баланс»."},{"id":7,"question":"Выбери точное русское значение выражения «take into account».","options":["выразить иначе","прояснить предположение","принять во внимание","выразить обеспокоенность"],"correctAnswer":"принять во внимание","explanation":"«take into account» — «принять во внимание»."},{"id":8,"question":"Какое выражение на британском английском соответствует «выразить обеспокоенность»?","options":["respond tactfully","raise a concern","clarify an assumption","make a valid point"],"correctAnswer":"raise a concern","explanation":"«raise a concern» — «выразить обеспокоенность»."}],"durationMinutes":10,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 41 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000005,'challenges','{"id":760300000000005,"title":"C1 · Разговорный · Знакомство и этикет · Challenge 5","description":"C1: знакомство и этикет. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"⚡","xp":46,"category":"Знакомство и этикет","track":"Разговорный","topic":"Знакомство и этикет","duration":"11 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «concede a point».","options":["выражаться точно","оспорить предположение","признать обоснованность довода","модерировать обсуждение"],"correctAnswer":"признать обоснованность довода","explanation":"«concede a point» — «признать обоснованность довода»."},{"id":2,"question":"Какое выражение на британском английском соответствует «оспорить предположение»?","options":["moderate a discussion","speak with precision","concede a point","challenge an assumption"],"correctAnswer":"challenge an assumption","explanation":"«challenge an assumption» — «оспорить предположение»."},{"id":3,"question":"Выбери точное русское значение выражения «adapt the register».","options":["уточнить оговорками утверждение","подобрать стиль общения","выражаться точно","передать тонкое различие"],"correctAnswer":"подобрать стиль общения","explanation":"«adapt the register» — «подобрать стиль общения»."},{"id":4,"question":"Выбери точное русское значение выражения «convey a subtle distinction».","options":["подобрать стиль общения","признать контраргумент","передать тонкое различие","оспорить предположение"],"correctAnswer":"передать тонкое различие","explanation":"«convey a subtle distinction» — «передать тонкое различие»."},{"id":5,"question":"Какое выражение на британском английском соответствует «уточнить оговорками утверждение»?","options":["concede a point","moderate a discussion","speak with precision","qualify a statement"],"correctAnswer":"qualify a statement","explanation":"«qualify a statement» — «уточнить оговорками утверждение»."},{"id":6,"question":"Выбери точное русское значение выражения «moderate a discussion».","options":["выражаться точно","модерировать обсуждение","оспорить предположение","подобрать стиль общения"],"correctAnswer":"модерировать обсуждение","explanation":"«moderate a discussion» — «модерировать обсуждение»."},{"id":7,"question":"Выбери точное русское значение выражения «draw an inference».","options":["выражаться точно","сделать вывод","передать тонкое различие","оспорить предположение"],"correctAnswer":"сделать вывод","explanation":"«draw an inference» — «сделать вывод»."},{"id":8,"question":"Какое выражение на британском английском соответствует «развернуть мысль»?","options":["draw an inference","qualify a statement","elaborate on a point","adapt the register"],"correctAnswer":"elaborate on a point","explanation":"«elaborate on a point» — «развернуть мысль»."}],"durationMinutes":11,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 46 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000006,'challenges','{"id":760300000000006,"title":"C2 · Разговорный · Знакомство и этикет · Challenge 6","description":"C2: знакомство и этикет. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C2","icon":"⚡","xp":54,"category":"Знакомство и этикет","track":"Разговорный","topic":"Знакомство и этикет","duration":"12 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «reconcile competing perspectives».","options":["оспорить исходную предпосылку","согласовать разные точки зрения","синтезировать противоположные взгляды","избегать необоснованной уверенности"],"correctAnswer":"согласовать разные точки зрения","explanation":"«reconcile competing perspectives» — «согласовать разные точки зрения»."},{"id":2,"question":"Какое выражение на британском английском соответствует «синтезировать противоположные взгляды»?","options":["foreground the implications","maintain rhetorical restraint","synthesise opposing views","articulate a caveat"],"correctAnswer":"synthesise opposing views","explanation":"«synthesise opposing views» — «синтезировать противоположные взгляды»."},{"id":3,"question":"Выбери точное русское значение выражения «make a nuanced distinction».","options":["провести тонкое различие","сформулировать оговорку","выдвинуть на первый план последствия","избегать необоснованной уверенности"],"correctAnswer":"провести тонкое различие","explanation":"«make a nuanced distinction» — «провести тонкое различие»."},{"id":4,"question":"Выбери точное русское значение выражения «foreground the implications».","options":["согласовать разные точки зрения","выдвинуть на первый план последствия","избегать необоснованной уверенности","сформулировать оговорку"],"correctAnswer":"выдвинуть на первый план последствия","explanation":"«foreground the implications» — «выдвинуть на первый план последствия»."},{"id":5,"question":"Какое выражение на британском английском соответствует «предложить ответ с оговорками»?","options":["distinguish intent from impact","invite a qualified response","reach a considered judgement","avoid unwarranted certainty"],"correctAnswer":"invite a qualified response","explanation":"«invite a qualified response» — «предложить ответ с оговорками»."},{"id":6,"question":"Выбери точное русское значение выражения «articulate a caveat».","options":["избегать необоснованной уверенности","прийти к взвешенному суждению","сформулировать оговорку","синтезировать противоположные взгляды"],"correctAnswer":"сформулировать оговорку","explanation":"«articulate a caveat» — «сформулировать оговорку»."},{"id":7,"question":"Выбери точное русское значение выражения «avoid unwarranted certainty».","options":["оспорить исходную предпосылку","избегать необоснованной уверенности","сохранять риторическую сдержанность","прийти к взвешенному суждению"],"correctAnswer":"избегать необоснованной уверенности","explanation":"«avoid unwarranted certainty» — «избегать необоснованной уверенности»."},{"id":8,"question":"Какое выражение на британском английском соответствует «оспорить исходную предпосылку»?","options":["make a nuanced distinction","expose a false dichotomy","synthesise opposing views","challenge the underlying premise"],"correctAnswer":"challenge the underlying premise","explanation":"«challenge the underlying premise» — «оспорить исходную предпосылку»."}],"durationMinutes":12,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 54 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
