я","меня зовут","спасибо"],"correctAnswer":"спасибо","explanation":"«thank you» — «спасибо»."},{"id":8,"question":"Какое выражение на британском английском соответствует «не могли бы вы мне помочь?»?","options":["my name is","could you help me?","nice to meet you","good morning"],"correctAnswer":"could you help me?","explanation":"«could you help me?» — «не могли бы вы мне помочь?»."}],"durationMinutes":7,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 26 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000008,'challenges','{"id":760300000000008,"title":"A2 · Разговорный · Повседневные ситуации · Challenge 8","description":"A2: повседневные ситуации. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"A2","icon":"⚡","xp":31,"category":"Повседневные ситуации","track":"Разговорный","topic":"Повседневные ситуации","duration":"8 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «I would like».","options":["дай мне знать","я согласен","я бы хотел","что ты думаешь?"],"correctAnswer":"я бы хотел","explanation":"«I would like» — «я бы хотел»."},{"id":2,"question":"Какое выражение на британском английском соответствует «я ищу»?","options":["I would like","by the way","I am looking for","what do you think?"],"correctAnswer":"I am looking for","explanation":"«I am looking for» — «я ищу»."},{"id":3,"question":"Выбери точное русское значение выражения «I disagree».","options":["я не согласен","не торопись","начнём?","я не уверен"],"correctAnswer":"я не согласен","explanation":"«I disagree» — «я не согласен»."},{"id":4,"question":"Выбери точное русское значение выражения «could I have».","options":["это зависит от обстоятельств","я не уверен","можно мне","я бы хотел"],"correctAnswer":"можно мне","explanation":"«could I have» — «можно мне»."},{"id":5,"question":"Какое выражение на британском английском соответствует «начнём?»?","options":["shall we start?","by the way","could I have","let me know"],"correctAnswer":"shall we start?","explanation":"«shall we start?» — «начнём?»."},{"id":6,"question":"Выбери точное русское значение выражения «I am not sure».","options":["я согласен","кстати","я не уверен","начнём?"],"correctAnswer":"я не уверен","explanation":"«I am not sure» — «я не уверен»."},{"id":7,"question":"Выбери точное русское значение выражения «by the way».","options":["что ты думаешь?","я ищу","кстати","я бы хотел"],"correctAnswer":"кстати","explanation":"«by the way» — «кстати»."},{"id":8,"question":"Какое выражение на британском английском соответствует «это зависит от обстоятельств»?","options":["I am looking for","I would like","it depends","I agree"],"correctAnswer":"it depends","explanation":"«it depends» — «это зависит от обстоятельств»."}],"durationMinutes":8,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 31 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000009,'challenges','{"id":760300000000009,"title":"B1 · Разговорный · Повседневные ситуации · Challenge 9","description":"B1: повседневные ситуации. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B1","icon":"⚡","xp":36,"category":"Повседневные ситуации","track":"Разговорный","topic":"Повседневные ситуации","duration":"9 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «as far as I know».","options":["с другой стороны","прояснить недоразумение","насколько мне известно","предложить идею"],"correctAnswer":"насколько мне известно","explanation":"«as far as I know» — «насколько мне известно»."},{"id":2,"question":"Какое выражение на британском английском соответствует «с нетерпением ждать»?","options":["that sounds reasonable","clear up a misunderstanding","to be honest","look forward to"],"correctAnswer":"look forward to","explanation":"«look forward to» — «с нетерпением ждать»."},{"id":3,"question":"Выбери точное русское значение выражения «take part in».","options":["по моему мнению","если честно","насколько мне известно","принимать участие в"],"correctAnswer":"принимать участие в","explanation":"«take part in» — «принимать участие в»."},{"id":4,"question":"Выбери точное русское значение выражения «in my opinion».","options":["по моему мнению","принимать участие в","с нетерпением ждать","насколько мне известно"],"correctAnswer":"по моему мнению","explanation":"«in my opinion» — «по моему мнению»."},{"id":5,"question":"Какое выражение на британском английском соответствует «с другой стороны»?","options":["that sounds reasonable","as far as I know","on the other hand","I see your point"],"correctAnswer":"on the other hand","explanation":"«on the other hand» — «с другой стороны»."},{"id":6,"question":"Выбери точное русское значение выражения «keep in touch».","options":["принимать участие в","я понимаю твою точку зрения","прояснить недоразумение","поддерживать связь"],"correctAnswer":"поддерживать связь","explanation":"«keep in touch» — «поддерживать связь»."},{"id":7,"question":"Выбери точное русское значение выражения «reach an agreement».","options":["достичь соглашения","поддерживать связь","принимать участие в","я понимаю твою точку зрения"],"correctAnswer":"достичь соглашения","explanation":"«reach an agreement» — «достичь соглашения»."},{"id":8,"question":"Какое выражение на британском английском соответствует «прояснить недоразумение»?","options":["take part in","reach an agreement","I see your point","clear up a misunderstanding"],"correctAnswer":"clear up a misunderstanding","explanation":"«clear up a misunderstanding» — «прояснить недоразумение»."}],"durationMinutes":9,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 36 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000010,'challenges','{"id":760300000000010,"title":"B2 · Разговорный · Повседневные ситуации · Challenge 10","description":"B2: повседневные ситуации. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B2","icon":"⚡","xp":41,"category":"Повседневные ситуации","track":"Разговорный","topic":"Повседневные ситуации","duration":"10 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «make a valid point».","options":["привести веский аргумент","взвесить варианты","выразить иначе","прояснить предположение"],"correctAnswer":"привести веский аргумент","explanation":"«make a valid point» — «привести веский аргумент»."},{"id":2,"question":"Какое выражение на британском английском соответствует «прийти к выводу»?","options":["come to a conclusion","respond tactfully","express a reservation","have mixed feelings"],"correctAnswer":"come to a conclusion","explanation":"«come to a conclusion» — «прийти к выводу»."},{"id":3,"question":"Выбери точное русское значение выражения «take into account».","options":["испытывать смешанные чувства","взвесить варианты","принять во внимание","найти баланс"],"correctAnswer":"принять во внимание","explanation":"«take into account» — «принять во внимание»."},{"id":4,"question":"Выбери точное русское значение выражения «strike a balance».","options":["прояснить предположение","взвесить варианты","найти баланс","ответить тактично"],"correctAnswer":"найти баланс","explanation":"«strike a balance» — «найти баланс»."},{"id":5,"question":"Какое выражение на британском английском соответствует «прояснить предположение»?","options":["raise a concern","clarify an assumption","put it another way","weigh up the options"],"correctAnswer":"clarify an assumption","explanation":"«clarify an assumption» — «прояснить предположение»."},{"id":6,"question":"Выбери точное русское значение выражения «respond tactfully».","options":["найти баланс","ответить тактично","выразить обеспокоенность","прийти к выводу"],"correctAnswer":"ответить тактично","explanation":"«respond tactfully» — «ответить тактично»."},{"id":7,"question":"Выбери точное русское значение выражения «express a reservation».","options":["испытывать смешанные чувства","выразить сомнение","найти баланс","разобраться с недопониманием"],"correctAnswer":"выразить сомнение","explanation":"«express a reservation» — «выразить сомнение»."},{"id":8,"question":"Какое выражение на британском английском соответствует «выразить обеспокоенность»?","options":["make a valid point","express a reservation","have mixed feelings","raise a concern"],"correctAnswer":"raise a concern","explanation":"«raise a concern» — «выразить обеспокоенность»."}],"durationMinutes":10,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 41 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000011,'challenges','{"id":760300000000011,"title":"C1 · Разговорный · Повседневные ситуации · Challenge 11","description":"C1: повседневные ситуации. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"⚡","xp":49,"category":"Повседневные ситуации","track":"Разговорный","topic":"Повседневные ситуации","duration":"11 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «draw an inference».","options":["оспорить предположение","уточнить оговорками утверждение","сделать вывод","найти точки соприкосновения"],"correctAnswer":"сделать вывод","explanation":"«draw an inference» — «сделать вывод»."},{"id":2,"question":"Какое выражение на британском английском соответствует «найти точки соприкосновения»?","options":["challenge an assumption","build common ground","frame a question neutrally","concede a point"],"correctAnswer":"build common ground","explanation":"«build common ground» — «найти точки соприкосновения»."},{"id":3,"question":"Выбери точное русское значение выражения «challenge an assumption».","options":["подобрать стиль общения","признать контраргумент","уточнить оговорками утверждение","оспорить предположение"],"correctAnswer":"оспорить предположение","explanation":"«challenge an assumption» — «оспорить предположение»."},{"id":4,"question":"Выбери точное русское значение выражения «speak with precision».","options":["выражаться точно","найти точки соприкосновения","подобрать стиль общения","признать контраргумент"],"correctAnswer":"выражаться точно","explanation":"«speak with precision» — «выражаться точно»."},{"id":5,"question":"Какое выражение на британском английском соответствует «признать обоснованность довода»?","options":["qualify a statement","concede a point","speak with precision","frame a question neutrally"],"correctAnswer":"concede a point","explanation":"«concede a point» — «признать обоснованность довода»."},{"id":6,"question":"Выбери точное русское значение выражения «elaborate on a point».","options":["развернуть мысль","уточнить оговорками утверждение","подобрать стиль общения","модерировать обсуждение"],"correctAnswer":"развернуть мысль","explanation":"«elaborate on a point» — «развернуть мысль»."},{"id":7,"question":"Выбери точное русское значение выражения «qualify a statement».","options":["уточнить оговорками утверждение","признать контраргумент","модерировать обсуждение","сформулировать вопрос нейтрально"],"correctAnswer":"уточнить оговорками утверждение","explanation":"«qualify a statement» — «уточнить оговорками утверждение»."},{"id":8,"question":"Какое выражение на британском английском соответствует «подобрать стиль общения»?","options":["acknowledge a counterargument","speak with precision","draw an inference","adapt the register"],"correctAnswer":"adapt the register","explanation":"«adapt the register» — «подобрать стиль общения»."}],"durationMinutes":11,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 49 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000012,'challenges','{"id":760300000000012,"title":"C2 · Разговорный · Повседневные ситуации · Challenge 12","description":"C2: повседневные ситуации. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C2","icon":"⚡","xp":51,"category":"Повседневные ситуации","track":"Разговорный","topic":"Повседневные ситуации","duration":"12 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «reconcile competing perspectives».","options":["прийти к взвешенному суждению","предложить ответ с оговорками","сформулировать оговорку","согласовать разные точки зрения"],"correctAnswer":"согласовать разные точки зрения","explanation":"«reconcile competing perspectives» — «согласовать разные точки зрения»."},{"id":2,"question":"Какое выражение на британском английском соответствует «выявить ложную дихотомию»?","options":["expose a false dichotomy","articulate a caveat","challenge the underlying premise","invite a qualified response"],"correctAnswer":"expose a false dichotomy","explanation":"«expose a false dichotomy» — «выявить ложную дихотомию»."},{"id":3,"question":"Выбери точное русское значение выражения «synthesise opposing views».","options":["синтезировать противоположные взгляды","согласовать разные точки зрения","сформулировать оговорку","прийти к взвешенному суждению"],"correctAnswer":"синтезировать противоположные взгляды","explanation":"«synthesise opposing views» — «синтезировать противоположные взгляды»."},{"id":4,"question":"Выбери точное русское значение выражения «maintain rhetorical restraint».","options":["предложить ответ с оговорками","сохранять риторическую сдержанность","синтезировать противоположные взгляды","оспорить исходную предпосылку"],"correctAnswer":"сохранять риторическую сдержанность","explanation":"«maintain rhetorical restraint» — «сохранять риторическую сдержанность»."},{"id":5,"question":"Какое выражение на британском английском соответствует «выдвинуть на первый план последствия»?","options":["synthesise opposing views","maintain rhetorical restraint","invite a qualified response","foreground the implications"],"correctAnswer":"foreground the implications","explanation":"«foreground the implications» — «выдвинуть на первый план последствия»."},{"id":6,"question":"Выбери точное русское значение выражения «challenge the underlying premise».","options":["предложить ответ с оговорками","оспорить исходную предпосылку","выявить ложную дихотомию","синтезировать противоположные взгляды"],"correctAnswer":"оспорить исходную предпосылку","explanation":"«challenge the underlying premise» — «оспорить исходную предпосылку»."},{"id":7,"question":"Выбери точное русское значение выражения «make a nuanced distinction».","options":["предложить ответ с оговорками","согласовать разные точки зрения","прийти к взвешенному суждению","провести тонкое различие"],"correctAnswer":"провести тонкое различие","explanation":"«make a nuanced distinction» — «провести тонкое различие»."},{"id":8,"question":"Какое выражение на британском английском соответствует «прийти к взвешенному суждению»?","options":["invite a qualified response","articulate a caveat","challenge the underlying premise","reach a considered judgement"],"correctAnswer":"reach a considered judgement","explanation":"«reach a considered judgement» — «прийти к взвешенному суждению»."}],"durationMinutes":12,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 51 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000013,'challenges','{"id":760300000000013,"title":"A1 · Разговорный · Мнение и общение · Challenge 13","description":"A1: мнение и общение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"A1","icon":"⚡","xp":26,"category":"Мнение и общение","track":"Разговорный","topic":"Мнение и общение","duration":"7 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «good morning».","options":["спасибо","доброе утро","не могли бы вы мне помочь?","как дела?"],"correctAnswer":"доброе утро","explanation":"«good morning» — «доброе утро»."},{"id":2,"question":"Какое выражение на британском английском соответствует «пожалуйста»?","options":["good morning","hello","please","I am sorry"],"correctAnswer":"please","explanation":"«please» — «пожалуйста»."},{"id":3,"question":"Выбери точное русское значение выражения «good evening».","options":["извините","как дела?","добрый вечер","доброе утро"],"correctAnswer":"добрый вечер","explanation":"«good evening» — «добрый вечер»."},{"id":4,"question":"Выбери точное русское значение выражения «thank you».","options":["спасибо","извините","мне жаль","как дела?"],"correctAnswer":"спасибо","explanation":"«thank you» — «спасибо»."},{"id":5,"question":"Какое выражение на британском английском соответствует «мне жаль»?","options":["I am sorry","excuse me","good evening","could you help me?"],"correctAnswer":"I am sorry","explanation":"«I am sorry» — «мне жаль»."},{"id":6,"question":"Выбери точное русское значение выражения «could you help me?».","options":["не могли бы вы мне помочь?","добрый вечер","привет","извините"],"correctAnswer":"не могли бы вы мне помочь?","explanation":"«could you help me?» — «не могли бы вы мне помочь?»."},{"id":7,"question":"Выбери точное русское значение выражения «see you later».","options":["доброе утро","увидимся позже","привет","извините"],"correctAnswer":"увидимся позже","explanation":"«see you later» — «увидимся позже»."},{"id":8,"question":"Какое выражение на британском английском соответствует «как дела?»?","options":["please","how are you?","I am sorry","could you help me?"],"correctAnswer":"how are you?","explanation":"«how are you?» — «как дела?»."}],"durationMinutes":7,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 26 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000014,'challenges','{"id":760300000000014,"title":"A2 · Разговорный · Мнение и общение · Challenge 14","description":"A2: мнение и общение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"A2","icon":"⚡","xp":31,"category":"Мнение и общение","track":"Разговорный","topic":"Мнение и общение","duration":"8 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «I am not sure».","options":["я не уверен","я согласен","я не согласен","я бы хотел"],"correctAnswer":"я не уверен","explanation":"«I am not sure» — «я не уверен»."},{"id":2,"question":"Какое выражение на британском английском соответствует «можно мне»?","options":["take your time","I am not sure","could I have","by the way"],"correctAnswer":"could I have","explanation":"«could I have» — «можно мне»."},{"id":3,"question":"Выбери точное русское значение выражения «shall we start?».","options":["не торопись","начнём?","что ты думаешь?","дай мне знать"],"correctAnswer":"начнём?","explanation":"«shall we start?» — «начнём?»."},{"id":4,"question":"Выбери точное русское значение выражения «it depends».","options":["что ты думаешь?","это зависит от обстоятельств","можно мне","не торопись"],"correctAnswer":"это зависит от обстоятельств","explanation":"«it depends» — «это зависит от обстоятельств»."},{"id":5,"question":"Какое выражение на британском английском соответствует «дай мне знать»?","options":["take your time","what do you think?","let me know","by the way"],"correctAnswer":"let me know","explanation":"«let me know» — «дай мне знать»."},{"id":6,"question":"Выбери точное русское значение выражения «what do you think?».","options":["что ты думаешь?","кстати","начнём?","я ищу"],"correctAnswer":"что ты думаешь?","explanation":"«what do you think?» — «что ты думаешь?»."},{"id":7,"question":"Выбери точное русское значение выражения «by the way».","options":["дай мне знать","я не уверен","что ты думаешь?","кстати"],"correctAnswer":"кстати","explanation":"«by the way» — «кстати»."},{"id":8,"question":"Какое выражение на британском английском соответствует «я согласен»?","options":["I agree","could I have","I disagree","by the way"],"correctAnswer":"I agree","explanation":"«I agree» — «я согласен»."}],"durationMinutes":8,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 31 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000015,'challenges','{"id":760300000000015,"title":"B1 · Разговорный · Мнение и общение · Challenge 15","description":"B1: мнение и общение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B1","icon":"⚡","xp":36,"category":"Мнение и общение","track":"Разговорный","topic":"Мнение и общение","duration":"9 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «make a suggestion».","options":["с нетерпением ждать","принимать участие в","предложить идею","прояснить недоразумение"],"correctAnswer":"предложить идею","explanation":"«make a suggestion» — «предложить идею»."},{"id":2,"question":"Какое выражение на британском английском соответствует «с нетерпением ждать»?","options":["I see your point","look forward to","clear up a misunderstanding","reach an agreement"],"correctAnswer":"look forward to","explanation":"«look forward to» — «с нетерпением ждать»."},{"id":3,"question":"Выбери точное русское значение выражения «that sounds reasonable».","options":["это звучит разумно","если честно","с другой стороны","достичь соглашения"],"correctAnswer":"это звучит разумно","explanation":"«that sounds reasonable» — «это звучит разумно»."},{"id":4,"question":"Выбери точное русское значение выражения «on the other hand».","options":["принимать участие в","предложить идею","с другой стороны","насколько мне известно"],"correctAnswer":"с другой стороны","explanation":"«on the other hand» — «с другой стороны»."},{"id":5,"question":"Какое выражение на британском английском соответствует «по моему мнению»?","options":["as far as I know","in my opinion","make a suggestion","clear up a misunderstanding"],"correctAnswer":"in my opinion","explanation":"«in my opinion» — «по моему мнению»."},{"id":6,"question":"Выбери точное русское значение выражения «to be honest».","options":["насколько мне известно","если честно","поддерживать связь","с другой стороны"],"correctAnswer":"если честно","explanation":"«to be honest» — «если честно»."},{"id":7,"question":"Выбери точное русское значение выражения «clear up a misunderstanding».","options":["принимать участие в","прояснить недоразумение","предложить идею","я понимаю твою точку зрения"],"correctAnswer":"прояснить недоразумение","explanation":"«clear up a misunderstanding» — «прояснить недоразумение»."},{"id":8,"question":"Какое выражение на британском английском соответствует «достичь соглашения»?","options":["that sounds reasonable","look forward to","on the other hand","reach an agreement"],"correctAnswer":"reach an agreement","explanation":"«reach an agreement» — «достичь соглашения»."}],"durationMinutes":9,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 36 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000016,'challenges','{"id":760300000000016,"title":"B2 · Разговорный · Мнение и общение · Challenge 16","description":"B2: мнение и общение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B2","icon":"⚡","xp":44,"category":"Мнение и общение","track":"Разговорный","topic":"Мнение и общение","duration":"10 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «clarify an assumption».","options":["взвесить варианты","выразить иначе","выразить сомнение","прояснить предположение"],"correctAnswer":"прояснить предположение","explanation":"«clarify an assumption» — «прояснить предположение»."},{"id":2,"question":"Какое выражение на британском английском соответствует «привести веский аргумент»?","options":["make a valid point","put it another way","express a reservation","raise a concern"],"correctAnswer":"make a valid point","explanation":"«make a valid point» — «привести веский аргумент»."},{"id":3,"question":"Выбери точное русское значение выражения «respond tactfully».","options":["прояснить предположение","ответить тактично","разобраться с недопониманием","принять во внимание"],"correctAnswer":"ответить тактично","explanation":"«respond tactfully» — «ответить тактично»."},{"id":4,"question":"Выбери точное русское значение выражения «address a misunderstanding».","options":["разобраться с недопониманием","выразить сомнение","выразить обеспокоенность","прийти к выводу"],"correctAnswer":"разобраться с недопониманием","explanation":"«address a misunderstanding» — «разобраться с недопониманием»."},{"id":5,"question":"Какое выражение на британском английском соответствует «найти баланс»?","options":["come to a conclusion","have mixed feelings","strike a balance","express a reservation"],"correctAnswer":"strike a balance","explanation":"«strike a balance» — «найти баланс»."},{"id":6,"question":"Выбери точное русское значение выражения «take into account».","options":["найти баланс","ответить тактично","принять во внимание","прояснить предположение"],"correctAnswer":"принять во внимание","explanation":"«take into account» — «принять во внимание»."},{"id":7,"question":"Выбери точное русское значение выражения «put it another way».","options":["привести веский аргумент","найти баланс","прийти к выводу","выразить иначе"],"correctAnswer":"выразить иначе","explanation":"«put it another way» — «выразить иначе»."},{"id":8,"question":"Какое выражение на британском английском соответствует «выразить сомнение»?","options":["address a misunderstanding","express a reservation","put it another way","strike a balance"],"correctAnswer":"express a reservation","explanation":"«express a reservation» — «выразить сомнение»."}],"durationMinutes":10,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 44 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000017,'challenges','{"id":760300000000017,"title":"C1 · Разговорный · Мнение и общение · Challenge 17","description":"C1: мнение и общение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"⚡","xp":46,"category":"Мнение и общение","track":"Разговорный","topic":"Мнение и общение","duration":"11 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «elaborate on a point».","options":["передать тонкое различие","признать контраргумент","развернуть мысль","найти точки соприкосновения"],"correctAnswer":"развернуть мысль","explanation":"«elaborate on a point» — «развернуть мысль»."},{"id":2,"question":"Какое выражение на британском английском соответствует «признать обоснованность довода»?","options":["concede a point","speak with precision","convey a subtle distinction","elaborate on a point"],"correctAnswer":"concede a point","explanation":"«concede a point» — «признать обоснованность довода»."},{"id":3,"question":"Выбери точное русское значение выражения «speak with precision».","options":["оспорить предположение","модерировать обсуждение","выражаться точно","уточнить оговорками утверждение"],"correctAnswer":"выражаться точно","explanation":"«speak with precision» — «выражаться точно»."},{"id":4,"question":"Выбери точное русское значение выражения «acknowledge a counterargument».","options":["найти точки соприкосновения","модерировать обсуждение","признать контраргумент","признать обоснованность довода"],"correctAnswer":"признать контраргумент","explanation":"«acknowledge a counterargument» — «признать контраргумент»."},{"id":5,"question":"Какое выражение на британском английском соответствует «оспорить предположение»?","options":["challenge an assumption","qualify a statement","acknowledge a counterargument","frame a question neutrally"],"correctAnswer":"challenge an assumption","explanation":"«challenge an assumption» — «оспорить предположение»."},{"id":6,"question":"Выбери точное русское значение выражения «convey a subtle distinction».","options":["найти точки соприкосновения","передать тонкое различие","модерировать обсуждение","уточнить оговорками утверждение"],"correctAnswer":"передать тонкое различие","explanation":"«convey a subtle distinction» — «передать тонкое различие»."},{"id":7,"question":"Выбери точное русское значение выражения «draw an inference».","options":["оспорить предположение","сделать вывод","передать тонкое различие","модерировать обсуждение"],"correctAnswer":"сделать вывод","explanation":"«draw an inference» — «сделать вывод»."},{"id":8,"question":"Какое выражение на британском английском соответствует «найти точки соприкосновения»?","options":["frame a question neutrally","build common ground","convey a subtle distinction","acknowledge a counterargument"],"correctAnswer":"build common ground","explanation":"«build common ground» — «найти точки соприкосновения»."}],"durationMinutes":11,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 46 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000018,'challenges','{"id":760300000000018,"title":"C2 · Разговорный · Мнение и общение · Challenge 18","description":"C2: мнение и общение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C2","icon":"⚡","xp":51,"category":"Мнение и общение","track":"Разговорный","topic":"Мнение и общение","duration":"12 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «synthesise opposing views».","options":["выдвинуть на первый план последствия","сформулировать оговорку","согласовать разные точки зрения","синтезировать противоположные взгляды"],"correctAnswer":"синтезировать противоположные взгляды","explanation":"«synthesise opposing views» — «синтезировать противоположные взгляды»."},{"id":2,"question":"Какое выражение на британском английском соответствует «провести тонкое различие»?","options":["avoid unwarranted certainty","foreground the implications","make a nuanced distinction","articulate a caveat"],"correctAnswer":"make a nuanced distinction","explanation":"«make a nuanced distinction» — «провести тонкое различие»."},{"id":3,"question":"Выбери точное русское значение выражения «invite a qualified response».","options":["сохранять риторическую сдержанность","провести тонкое различие","предложить ответ с оговорками","оспорить исходную предпосылку"],"correctAnswer":"предложить ответ с оговорками","explanation":"«invite a qualified response» — «предложить ответ с оговорками»."},{"id":4,"question":"Выбери точное русское значение выражения «distinguish intent from impact».","options":["разграничить намерение и результат","выдвинуть на первый план последствия","провести тонкое различие","согласовать разные точки зрения"],"correctAnswer":"разграничить намерение и результат","explanation":"«distinguish intent from impact» — «разграничить намерение и результат»."},{"id":5,"question":"Какое выражение на британском английском соответствует «согласовать разные точки зрения»?","options":["invite a qualified response","synthesise opposing views","reach a considered judgement","reconcile competing perspectives"],"correctAnswer":"reconcile competing perspectives","explanation":"«reconcile competing perspectives» — «согласовать разные точки зрения»."},{"id":6,"question":"Выбери точное русское значение выражения «avoid unwarranted certainty».","options":["выявить ложную дихотомию","избегать необоснованной уверенности","разграничить намерение и результат","сохранять риторическую сдержанность"],"correctAnswer":"избегать необоснованной уверенности","explanation":"«avoid unwarranted certainty» — «избегать необоснованной уверенности»."},{"id":7,"question":"Выбери точное русское значение выражения «foreground the implications».","options":["выдвинуть на первый план последствия","разграничить намерение и результат","оспорить исходную предпосылку","согласовать разные точки зрения"],"correctAnswer":"выдвинуть на первый план последствия","explanation":"«foreground the implications» — «выдвинуть на первый план последствия»."},{"id":8,"question":"Какое выражение на британском английском соответствует «выявить ложную дихотомию»?","options":["foreground the implications","articulate a caveat","expose a false dichotomy","challenge the underlying premise"],"correctAnswer":"expose a false dichotomy","explanation":"«expose a false dichotomy» — «выявить ложную дихотомию»."}],"durationMinutes":12,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 51 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000019,'challenges','{"id":760300000000019,"title":"A1 · Разговорный · Диалог и уточнение · Challenge 19","description":"A1: диалог и уточнение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"A1","icon":"⚡","xp":26,"category":"Диалог и уточнение","track":"Разговорный","topic":"Диалог и уточнение","duration":"7 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «good evening».","options":["добрый вечер","извините","привет","как дела?"],"correctAnswer":"добрый вечер","explanation":"«good evening» — «добрый вечер»."},{"id":2,"question":"Какое выражение на британском английском соответствует «меня зовут»?","options":["how are you?","I am sorry","my name is","good morning"],"correctAnswer":"my name is","explanation":"«my name is» — «меня зовут»."},{"id":3,"question":"Выбери точное русское значение выражения «excuse me».","options":["не могли бы вы мне помочь?","как дела?","извините","меня зовут"],"correctAnswer":"извините","explanation":"«excuse me» — «извините»."},{"id":4,"question":"Выбери точное русское значение выражения «I am sorry».","options":["добрый вечер","извините","мне жаль","привет"],"correctAnswer":"мне жаль","explanation":"«I am sorry» — «мне жаль»."},{"id":5,"question":"Какое выражение на британском английском соответствует «привет»?","options":["my name is","good evening","good morning","hello"],"correctAnswer":"hello","explanation":"«hello» — «привет»."},{"id":6,"question":"Выбери точное русское значение выражения «good morning».","options":["увидимся позже","доброе утро","мне жаль","как дела?"],"correctAnswer":"доброе утро","explanation":"«good morning» — «доброе утро»."},{"id":7,"question":"Выбери точное русское значение выражения «see you later».","options":["увидимся позже","меня зовут","извините","добрый вечер"],"correctAnswer":"увидимся позже","explanation":"«see you later» — «увидимся позже»."},{"id":8,"question":"Какое выражение на британском английском соответствует «не могли бы вы мне помочь?»?","options":["please","could you help me?","hello","my name is"],"correctAnswer":"could you help me?","explanation":"«could you help me?» — «не могли бы вы мне помочь?»."}],"durationMinutes":7,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 26 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000020,'challenges','{"id":760300000000020,"title":"A2 · Разговорный · Диалог и уточнение · Challenge 20","description":"A2: диалог и уточнение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"A2","icon":"⚡","xp":31,"category":"Диалог и уточнение","track":"Разговорный","topic":"Диалог и уточнение","duration":"8 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «take your time».","options":["я не согласен","не торопись","кстати","что ты думаешь?"],"correctAnswer":"не торопись","explanation":"«take your time» — «не торопись»."},{"id":2,"question":"Какое выражение на британском английском соответствует «что ты думаешь?»?","options":["I disagree","what do you think?","I am not sure","it depends"],"correctAnswer":"what do you think?","explanation":"«what do you think?» — «что ты думаешь?»."},{"id":3,"question":"Выбери точное русское значение выражения «shall we start?».","options":["кстати","я не уверен","начнём?","это зависит от обстоятельств"],"correctAnswer":"начнём?","explanation":"«shall we start?» — «начнём?»."},{"id":4,"question":"Выбери точное русское значение выражения «I agree».","options":["я согласен","я не уверен","это зависит от обстоятельств","кстати"],"correctAnswer":"я согласен","explanation":"«I agree» — «я согласен»."},{"id":5,"question":"Какое выражение на британском английском соответствует «это зависит от обстоятельств»?","options":["it depends","I am looking for","take your time","I agree"],"correctAnswer":"it depends","explanation":"«it depends» — «это зависит от обстоятельств»."},{"id":6,"question":"Выбери точное русское значение выражения «I am not sure».","options":["это зависит от обстоятельств","я не уверен","начнём?","что ты думаешь?"],"correctAnswer":"я не уверен","explanation":"«I am not sure» — «я не уверен»."},{"id":7,"question":"Выбери точное русское значение выражения «I disagree».","options":["что ты думаешь?","я бы хотел","я не уверен","я не согласен"],"correctAnswer":"я не согласен","explanation":"«I disagree» — «я не согласен»."},{"id":8,"question":"Какое выражение на британском английском соответствует «кстати»?","options":["I am looking for","I am not sure","by the way","what do you think?"],"correctAnswer":"by the way","explanation":"«by the way» — «кстати»."}],"durationMinutes":8,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 31 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000021,'challenges','{"id":760300000000021,"title":"B1 · Разговорный · Диалог и уточнение · Challenge 21","description":"B1: диалог и уточнение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B1","icon":"⚡","xp":39,"category":"Диалог и уточнение","track":"Разговорный","topic":"Диалог и уточнение","duration":"9 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «look forward to».","options":["это звучит разумно","с нетерпением ждать","принимать участие в","насколько мне известно"],"correctAnswer":"с нетерпением ждать","explanation":"«look forward to» — «с нетерпением ждать»."},{"id":2,"question":"Какое выражение на британском английском соответствует «принимать участие в»?","options":["on the other hand","that sounds reasonable","take part in","to be honest"],"correctAnswer":"take part in","explanation":"«take part in» — «принимать участие в»."},{"id":3,"question":"Выбери точное русское значение выражения «I see your point».","options":["предложить идею","с нетерпением ждать","принимать участие в","я понимаю твою точку зрения"],"correctAnswer":"я понимаю твою точку зрения","explanation":"«I see your point» — «я понимаю твою точку зрения»."},{"id":4,"question":"Выбери точное русское значение выражения «reach an agreement».","options":["если честно","предложить идею","достичь соглашения","прояснить недоразумение"],"correctAnswer":"достичь соглашения","explanation":"«reach an agreement» — «достичь соглашения»."},{"id":5,"question":"Какое выражение на британском английском соответствует «насколько мне известно»?","options":["to be honest","clear up a misunderstanding","in my opinion","as far as I know"],"correctAnswer":"as far as I know","explanation":"«as far as I know» — «насколько мне известно»."},{"id":6,"question":"Выбери точное русское значение выражения «clear up a misunderstanding».","options":["с нетерпением ждать","принимать участие в","прояснить недоразумение","с другой стороны"],"correctAnswer":"прояснить недоразумение","explanation":"«clear up a misunderstanding» — «прояснить недоразумение»."},{"id":7,"question":"Выбери точное русское значение выражения «keep in touch».","options":["достичь соглашения","с нетерпением ждать","поддерживать связь","я понимаю твою точку зрения"],"correctAnswer":"поддерживать связь","explanation":"«keep in touch» — «поддерживать связь»."},{"id":8,"question":"Какое выражение на британском английском соответствует «предложить идею»?","options":["take part in","reach an agreement","make a suggestion","as far as I know"],"correctAnswer":"make a suggestion","explanation":"«make a suggestion» — «предложить идею»."}],"durationMinutes":9,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 39 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000022,'challenges','{"id":760300000000022,"title":"B2 · Разговорный · Диалог и уточнение · Challenge 22","description":"B2: диалог и уточнение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B2","icon":"⚡","xp":41,"category":"Диалог и уточнение","track":"Разговорный","topic":"Диалог и уточнение","duration":"10 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «take into account».","options":["испытывать смешанные чувства","выразить сомнение","прийти к выводу","принять во внимание"],"correctAnswer":"принять во внимание","explanation":"«take into account» — «принять во внимание»."},{"id":2,"question":"Какое выражение на британском английском соответствует «привести веский аргумент»?","options":["make a valid point","put it another way","come to a conclusion","raise a concern"],"correctAnswer":"make a valid point","explanation":"«make a valid point» — «привести веский аргумент»."},{"id":3,"question":"Выбери точное русское значение выражения «put it another way».","options":["выразить иначе","принять во внимание","выразить сомнение","испытывать смешанные чувства"],"correctAnswer":"выразить иначе","explanation":"«put it another way» — «выразить иначе»."},{"id":4,"question":"Выбери точное русское значение выражения «respond tactfully».","options":["найти баланс","разобраться с недопониманием","ответить тактично","принять во внимание"],"correctAnswer":"ответить тактично","explanation":"«respond tactfully» — «ответить тактично»."},{"id":5,"question":"Какое выражение на британском английском соответствует «выразить сомнение»?","options":["weigh up the options","make a valid point","express a reservation","take into account"],"correctAnswer":"express a reservation","explanation":"«express a reservation» — «выразить сомнение»."},{"id":6,"question":"Выбери точное русское значение выражения «address a misunderstanding».","options":["выразить иначе","разобраться с недопониманием","прояснить предположение","ответить тактично"],"correctAnswer":"разобраться с недопониманием","explanation":"«address a misunderstanding» — «разобраться с недопониманием»."},{"id":7,"question":"Выбери точное русское значение выражения «raise a concern».","options":["выразить иначе","взвесить варианты","выразить обеспокоенность","прояснить предположение"],"correctAnswer":"выразить обеспокоенность","explanation":"«raise a concern» — «выразить обеспокоенность»."},{"id":8,"question":"Какое выражение на британском английском соответствует «прояснить предположение»?","options":["clarify an assumption","strike a balance","weigh up the options","respond tactfully"],"correctAnswer":"clarify an assumption","explanation":"«clarify an assumption» — «прояснить предположение»."}],"durationMinutes":10,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 41 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000023,'challenges','{"id":760300000000023,"title":"C1 · Разговорный · Диалог и уточнение · Challenge 23","description":"C1: диалог и уточнение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"⚡","xp":46,"category":"Диалог и уточнение","track":"Разговорный","topic":"Диалог и уточнение","duration":"11 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «elaborate on a point».","options":["выражаться точно","уточнить оговорками утверждение","найти точки соприкосновения","развернуть мысль"],"correctAnswer":"развернуть мысль","explanation":"«elaborate on a point» — «развернуть мысль»."},{"id":2,"question":"Какое выражение на британском английском соответствует «сформулировать вопрос нейтрально»?","options":["moderate a discussion","convey a subtle distinction","draw an inference","frame a question neutrally"],"correctAnswer":"frame a question neutrally","explanation":"«frame a question neutrally» — «сформулировать вопрос нейтрально»."},{"id":3,"question":"Выбери точное русское значение выражения «speak with precision».","options":["модерировать обсуждение","выражаться точно","уточнить оговорками утверждение","оспорить предположение"],"correctAnswer":"выражаться точно","explanation":"«speak with precision» — «выражаться точно»."},{"id":4,"question":"Выбери точное русское значение выражения «acknowledge a counterargument».","options":["признать контраргумент","передать тонкое различие","выражаться точно","найти точки соприкосновения"],"correctAnswer":"признать контраргумент","explanation":"«acknowledge a counterargument» — «признать контраргумент»."},{"id":5,"question":"Какое выражение на британском английском соответствует «передать тонкое различие»?","options":["elaborate on a point","convey a subtle distinction","frame a question neutrally","adapt the register"],"correctAnswer":"convey a subtle distinction","explanation":"«convey a subtle distinction» — «передать тонкое различие»."},{"id":6,"question":"Выбери точное русское значение выражения «qualify a statement».","options":["передать тонкое различие","развернуть мысль","уточнить оговорками утверждение","модерировать обсуждение"],"correctAnswer":"уточнить оговорками утверждение","explanation":"«qualify a statement» — «уточнить оговорками утверждение»."},{"id":7,"question":"Выбери точное русское значение выражения «concede a point».","options":["оспорить предположение","признать контраргумент","признать обоснованность довода","сформулировать вопрос нейтрально"],"correctAnswer":"признать обоснованность довода","explanation":"«concede a point» — «признать обоснованность довода»."},{"id":8,"question":"Какое выражение на британском английском соответствует «найти точки соприкосновения»?","options":["moderate a discussion","build common ground","convey a subtle distinction","frame a question neutrally"],"correctAnswer":"build common ground","explanation":"«build common ground» — «найти точки соприкосновения»."}],"durationMinutes":11,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 46 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000024,'challenges','{"id":760300000000024,"title":"C2 · Разговорный · Диалог и уточнение · Challenge 24","description":"C2: диалог и уточнение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C2","icon":"⚡","xp":51,"category":"Диалог и уточнение","track":"Разговорный","topic":"Диалог и уточнение","duration":"12 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «reconcile competing perspectives».","options":["сформулировать оговорку","предложить ответ с оговорками","оспорить исходную предпосылку","согласовать разные точки зрения"],"correctAnswer":"согласовать разные точки зрения","explanation":"«reconcile competing perspectives» — «согласовать разные точки зрения»."},{"id":2,"question":"Какое выражение на британском английском соответствует «оспорить исходную предпосылку»?","options":["challenge the underlying premise","distinguish intent from impact","make a nuanced distinction","invite a qualified response"],"correctAnswer":"challenge the underlying premise","explanation":"«challenge the underlying premise» — «оспорить исходную предпосылку»."},{"id":3,"question":"Выбери точное русское значение выражения «invite a qualified response».","options":["предложить ответ с оговорками","синтезировать противоположные взгляды","провести тонкое различие","оспорить исходную предпосылку"],"correctAnswer":"предложить ответ с оговорками","explanation":"«invite a qualified response» — «предложить ответ с оговорками»."},{"id":4,"question":"Выбери точное русское значение выражения «avoid unwarranted certainty».","options":["избегать необоснованной уверенности","предложить ответ с оговорками","прийти к взвешенному суждению","провести тонкое различие"],"correctAnswer":"избегать необоснованной уверенности","explanation":"«avoid unwarranted certainty» — «избегать необоснованной уверенности»."},{"id":5,"question":"Какое выражение на британском английском соответствует «выдвинуть на первый план последствия»?","options":["invite a qualified response","maintain rhetorical restraint","foreground the implications","articulate a caveat"],"correctAnswer":"foreground the implications","explanation":"«foreground the implications» — «выдвинуть на первый план последствия»."},{"id":6,"question":"Выбери точное русское значение выражения «synthesise opposing views».","options":["синтезировать противоположные взгляды","сформулировать оговорку","сохранять риторическую сдержанность","выявить ложную дихотомию"],"correctAnswer":"синтезировать противоположные взгляды","explanation":"«synthesise opposing views» — «синтезировать противоположные взгляды»."},{"id":7,"question":"Выбери точное русское значение выражения «make a nuanced distinction».","options":["провести тонкое различие","сформулировать оговорку","синтезировать противоположные взгляды","разграничить намерение и результат"],"correctAnswer":"провести тонкое различие","explanation":"«make a nuanced distinction» — «провести тонкое различие»."},{"id":8,"question":"Какое выражение на британском английском соответствует «разграничить намерение и результат»?","options":["distinguish intent from impact","reconcile competing perspectives","articulate a caveat","make a nuanced distinction"],"correctAnswer":"distinguish intent from impact","explanation":"«distinguish intent from impact» — «разграничить намерение и результат»."}],"durationMinutes":12,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 51 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000025,'challenges','{"id":760300000000025,"title":"A1 · Разговорный · Точность высказывания · Challenge 25","description":"A1: точность высказывания. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"A1","icon":"⚡","xp":26,"category":"Точность высказывания","track":"Разговорный","topic":"Точность высказывания","duration":"7 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «please».","options":["не могли бы вы мне помочь?","как дела?","добрый вечер","пожалуйста"],"correctAnswer":"пожалуйста","explanation":"«please» — «пожалуйста»."},{"id":2,"question":"Какое выражение на британском английском соответствует «добрый вечер»?","options":["could you help me?","good evening","good morning","thank you"],"correctAnswer":"good evening","explanation":"«good evening» — «добрый вечер»."},{"id":3,"question":"Выбери точное русское значение выражения «good morning».","options":["доброе утро","как дела?","привет","добрый вечер"],"correctAnswer":"доброе утро","explanation":"«good morning» — «доброе утро»."},{"id":4,"question":"Выбери точное русское значение выражения «excuse me».","options":["пожалуйста","привет","извините","не могли бы вы мне помочь?"],"correctAnswer":"извините","explanation":"«excuse me» — «извините»."},{"id":5,"question":"Какое выражение на британском английском соответствует «как дела?»?","options":["I am sorry","how are you?","good evening","could you help me?"],"correctAnswer":"how are you?","explanation":"«how are you?» — «как дела?»."},{"id":6,"question":"Выбери точное русское значение выражения «nice to meet you».","options":["доброе утро","как дела?","приятно познакомиться","спасибо"],"correctAnswer":"приятно познакомиться","explanation":"«nice to meet you» — «приятно познакомиться»."},{"id":7,"question":"Выбери точное русское значение выражения «my name is».","options":["мне жаль","как дела?","не могли бы вы мне помочь?","меня зовут"],"correctAnswer":"меня зовут","explanation":"«my name is» — «меня зовут»."},{"id":8,"question":"Какое выражение на британском английском соответствует «не могли бы вы мне помочь?»?","options":["thank you","could you help me?","my name is","nice to meet you"],"correctAnswer":"could you help me?","explanation":"«could you help me?» — «не могли бы вы мне помочь?»."}],"durationMinutes":7,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 26 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000026,'challenges','{"id":760300000000026,"title":"A2 · Разговорный · Точность высказывания · Challenge 26","description":"A2: точность высказывания. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"A2","icon":"⚡","xp":34,"category":"Точность высказывания","track":"Разговорный","topic":"Точность высказывания","duration":"8 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «it depends».","options":["дай мне знать","это зависит от обстоятельств","я ищу","кстати"],"correctAnswer":"это зависит от обстоятельств","explanation":"«it depends» — «это зависит от обстоятельств»."},{"id":2,"question":"Какое выражение на британском английском соответствует «не торопись»?","options":["I would like","take your time","I am not sure","it depends"],"correctAnswer":"take your time","explanation":"«take your time» — «не торопись»."},{"id":3,"question":"Выбери точное русское значение выражения «I disagree».","options":["я не согласен","дай мне знать","кстати","я не уверен"],"correctAnswer":"я не согласен","explanation":"«I disagree» — «я не согласен»."},{"id":4,"question":"Выбери точное русское значение выражения «I am looking for».","options":["я ищу","я не согласен","я бы хотел","начнём?"],"correctAnswer":"я ищу","explanation":"«I am looking for» — «я ищу»."},{"id":5,"question":"Какое выражение на британском английском соответствует «можно мне»?","options":["I would like","I am not sure","could I have","I am looking for"],"correctAnswer":"could I have","explanation":"«could I have» — «можно мне»."},{"id":6,"question":"Выбери точное русское значение выражения «I agree».","options":["я не уверен","я не согласен","я согласен","не торопись"],"correctAnswer":"я согласен","explanation":"«I agree» — «я согласен»."},{"id":7,"question":"Выбери точное русское значение выражения «what do you think?».","options":["можно мне","кстати","что ты думаешь?","дай мне знать"],"correctAnswer":"что ты думаешь?","explanation":"«what do you think?» — «что ты думаешь?»."},{"id":8,"question":"Какое выражение на британском английском соответствует «я бы хотел»?","options":["I disagree","what do you think?","by the way","I would like"],"correctAnswer":"I would like","explanation":"«I would like» — «я бы хотел»."}],"durationMinutes":8,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 34 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000027,'challenges','{"id":760300000000027,"title":"B1 · Разговорный · Точность высказывания · Challenge 27","description":"B1: точность высказывания. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B1","icon":"⚡","xp":36,"category":"Точность высказывания","track":"Разговорный","topic":"Точность высказывания","duration":"9 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «that sounds reasonable».","options":["поддерживать связь","достичь соглашения","это звучит разумно","принимать участие в"],"correctAnswer":"это звучит разумно","explanation":"«that sounds reasonable» — «это звучит разумно»."},{"id":2,"question":"Какое выражение на британском английском соответствует «насколько мне известно»?","options":["on the other hand","clear up a misunderstanding","as far as I know","I see your point"],"correctAnswer":"as far as I know","explanation":"«as far as I know» — «насколько мне известно»."},{"id":3,"question":"Выбери точное русское значение выражения «take part in».","options":["если честно","принимать участие в","с другой стороны","с нетерпением ждать"],"correctAnswer":"принимать участие в","explanation":"«take part in» — «принимать участие в»."},{"id":4,"question":"Выбери точное русское значение выражения «on the other hand».","options":["насколько мне известно","с другой стороны","это звучит разумно","принимать участие в"],"correctAnswer":"с другой стороны","explanation":"«on the other hand» — «с другой стороны»."},{"id":5,"question":"Какое выражение на британском английском соответствует «предложить идею»?","options":["on the other hand","make a suggestion","in my opinion","that sounds reasonable"],"correctAnswer":"make a suggestion","explanation":"«make a suggestion» — «предложить идею»."},{"id":6,"question":"Выбери точное русское значение выражения «keep in touch».","options":["это звучит разумно","я понимаю твою точку зрения","поддерживать связь","насколько мне известно"],"correctAnswer":"поддерживать связь","explanation":"«keep in touch» — «поддерживать связь»."},{"id":7,"question":"Выбери точное русское значение выражения «look forward to».","options":["прояснить недоразумение","поддерживать связь","с нетерпением ждать","я понимаю твою точку зрения"],"correctAnswer":"с нетерпением ждать","explanation":"«look forward to» — «с нетерпением ждать»."},{"id":8,"question":"Какое выражение на британском английском соответствует «если честно»?","options":["to be honest","clear up a misunderstanding","that sounds reasonable","keep in touch"],"correctAnswer":"to be honest","explanation":"«to be honest» — «если честно»."}],"durationMinutes":9,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 36 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000028,'challenges','{"id":760300000000028,"title":"B2 · Разговорный · Точность высказывания · Challenge 28","description":"B2: точность высказывания. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B2","icon":"⚡","xp":41,"category":"Точность высказывания","track":"Разговорный","topic":"Точность высказывания","duration":"10 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «strike a balance».","options":["найти баланс","разобраться с недопониманием","прояснить предположение","выразить сомнение"],"correctAnswer":"найти баланс","explanation":"«strike a balance» — «найти баланс»."},{"id":2,"question":"Какое выражение на британском английском соответствует «привести веский аргумент»?","options":["weigh up the options","make a valid point","raise a concern","put it another way"],"correctAnswer":"make a valid point","explanation":"«make a valid point» — «привести веский аргумент»."},{"id":3,"question":"Выбери точное русское значение выражения «express a reservation».","options":["выразить иначе","прийти к выводу","найти баланс","выразить сомнение"],"correctAnswer":"выразить сомнение","explanation":"«express a reservation» — «выразить сомнение»."},{"id":4,"question":"Выбери точное русское значение выражения «have mixed feelings».","options":["выразить иначе","привести веский аргумент","выразить обеспокоенность","испытывать смешанные чувства"],"correctAnswer":"испытывать смешанные чувства","explanation":"«have mixed feelings» — «испытывать смешанные чувства»."},{"id":5,"question":"Какое выражение на британском английском соответствует «выразить обеспокоенность»?","options":["raise a concern","take into account","make a valid point","clarify an assumption"],"correctAnswer":"raise a concern","explanation":"«raise a concern» — «выразить обеспокоенность»."},{"id":6,"question":"Выбери точное русское значение выражения «put it another way».","options":["найти баланс","ответить тактично","выразить сомнение","выразить иначе"],"correctAnswer":"выразить иначе","explanation":"«put it another way» — «выразить иначе»."},{"id":7,"question":"Выбери точное русское значение выражения «clarify an assumption».","options":["прояснить предположение","ответить тактично","взвесить варианты","выразить иначе"],"correctAnswer":"прояснить предположение","explanation":"«clarify an assumption» — «прояснить предположение»."},{"id":8,"question":"Какое выражение на британском английском соответствует «прийти к выводу»?","options":["address a misunderstanding","come to a conclusion","express a reservation","take into account"],"correctAnswer":"come to a conclusion","explanation":"«come to a conclusion» — «прийти к выводу»."}],"durationMinutes":10,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 41 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000029,'challenges','{"id":760300000000029,"title":"C1 · Разговорный · Точность высказывания · Challenge 29","description":"C1: точность высказывания. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"⚡","xp":46,"category":"Точность высказывания","track":"Разговорный","topic":"Точность высказывания","duration":"11 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «challenge an assumption».","options":["развернуть мысль","модерировать обсуждение","сделать вывод","оспорить предположение"],"correctAnswer":"оспорить предположение","explanation":"«challenge an assumption» — «оспорить предположение»."},{"id":2,"question":"Какое выражение на британском английском соответствует «передать тонкое различие»?","options":["concede a point","build common ground","convey a subtle distinction","moderate a discussion"],"correctAnswer":"convey a subtle distinction","explanation":"«convey a subtle distinction» — «передать тонкое различие»."},{"id":3,"question":"Выбери точное русское значение выражения «build common ground».","options":["признать контраргумент","уточнить оговорками утверждение","найти точки соприкосновения","оспорить предположение"],"correctAnswer":"найти точки соприкосновения","explanation":"«build common ground» — «найти точки соприкосновения»."},{"id":4,"question":"Выбери точное русское значение выражения «concede a point».","options":["развернуть мысль","подобрать стиль общения","признать обоснованность довода","найти точки соприкосновения"],"correctAnswer":"признать обоснованность довода","explanation":"«concede a point» — «признать обоснованность довода»."},{"id":5,"question":"Какое выражение на британском английском соответствует «подобрать стиль общения»?","options":["adapt the register","build common ground","convey a subtle distinction","elaborate on a point"],"correctAnswer":"adapt the register","explanation":"«adapt the register» — «подобрать стиль общения»."},{"id":6,"question":"Выбери точное русское значение выражения «qualify a statement».","options":["модерировать обсуждение","передать тонкое различие","сделать вывод","уточнить оговорками утверждение"],"correctAnswer":"уточнить оговорками утверждение","explanation":"«qualify a statement» — «уточнить оговорками утверждение»."},{"id":7,"question":"Выбери точное русское значение выражения «draw an inference».","options":["признать контраргумент","оспорить предположение","сделать вывод","развернуть мысль"],"correctAnswer":"сделать вывод","explanation":"«draw an inference» — «сделать вывод»."},{"id":8,"question":"Какое выражение на британском английском соответствует «модерировать обсуждение»?","options":["elaborate on a point","concede a point","qualify a statement","moderate a discussion"],"correctAnswer":"moderate a discussion","explanation":"«moderate a discussion» — «модерировать обсуждение»."}],"durationMinutes":11,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 46 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000030,'challenges','{"id":760300000000030,"title":"C2 · Разговорный · Точность высказывания · Challenge 30","description":"C2: точность высказывания. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C2","icon":"⚡","xp":51,"category":"Точность высказывания","track":"Разговорный","topic":"Точность высказывания","duration":"12 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «reconcile competing perspectives».","options":["выявить ложную дихотомию","разграничить намерение и результат","оспорить исходную предпосылку","согласовать разные точки зрения"],"correctAnswer":"согласовать разные точки зрения","explanation":"«reconcile competing perspectives» — «согласовать разные точки зрения»."},{"id":2,"question":"Какое выражение на британском английском соответствует «сохранять риторическую сдержанность»?","options":["articulate a caveat","maintain rhetorical restraint","reconcile competing perspectives","invite a qualified response"],"correctAnswer":"maintain rhetorical restraint","explanation":"«maintain rhetorical restraint» — «сохранять риторическую сдержанность»."},{"id":3,"question":"Выбери точное русское значение выражения «synthesise opposing views».","options":["синтезировать противоположные взгляды","сформулировать оговорку","предложить ответ с оговорками","разграничить намерение и результат"],"correctAnswer":"синтезировать противоположные взгляды","explanation":"«synthesise opposing views» — «синтезировать противоположные взгляды»."},{"id":4,"question":"Выбери точное русское значение выражения «foreground the implications».","options":["выявить ложную дихотомию","выдвинуть на первый план последствия","прийти к взвешенному суждению","сформулировать оговорку"],"correctAnswer":"выдвинуть на первый план последствия","explanation":"«foreground the implications» — «выдвинуть на первый план последствия»."},{"id":5,"question":"Какое выражение на британском английском соответствует «избегать необоснованной уверенности»?","options":["challenge the underlying premise","invite a qualified response","make a nuanced distinction","avoid unwarranted certainty"],"correctAnswer":"avoid unwarranted certainty","explanation":"«avoid unwarranted certainty» — «избегать необоснованной уверенности»."},{"id":6,"question":"Выбери точное русское значение выражения «articulate a caveat».","options":["согласовать разные точки зрения","сохранять риторическую сдержанность","сформулировать оговорку","провести тонкое различие"],"correctAnswer":"сформулировать оговорку","explanation":"«articulate a caveat» — «сформулировать оговорку»."},{"id":7,"question":"Выбери точное русское значение выражения «reach a considered judgement».","options":["прийти к взвешенному суждению","выдвинуть на первый план последствия","сохранять риторическую сдержанность","разграничить намерение и результат"],"correctAnswer":"прийти к взвешенному суждению","explanation":"«reach a considered judgement» — «прийти к взвешенному суждению»."},{"id":8,"question":"Какое выражение на британском английском соответствует «оспорить исходную предпосылку»?","options":["challenge the underlying premise","articulate a caveat","distinguish intent from impact","make a nuanced distinction"],"correctAnswer":"challenge the underlying premise","explanation":"«challenge the underlying premise» — «оспорить исходную предпосылку»."}],"durationMinutes":12,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 51 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000031,'challenges','{"id":760300000000031,"title":"A1 · Разговорный · Знакомство и этикет · Challenge 31","description":"A1: знакомство и этикет. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"A1","icon":"⚡","xp":29,"category":"Знакомство и этикет","track":"Разговорный","topic":"Знакомство и этикет","duration":"7 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «please».","options":["доброе утро","меня зовут","добрый вечер","пожалуйста"],"correctAnswer":"пожалуйста","explanation":"«please» — «пожалуйста»."},{"id":2,"question":"Какое выражение на британском английском соответствует «привет»?","options":["hello","I am sorry","see you later","could you help me?"],"correctAnswer":"hello","explanation":"«hello» — «привет»."},{"id":3,"question":"Выбери точное русское значение выражения «excuse me».","options":["как дела?","извините","не могли бы вы мне помочь?","привет"],"correctAnswer":"извините","explanation":"«excuse me» — «извините»."},{"id":4,"question":"Выбери точное русское значение выражения «good evening».","options":["привет","увидимся позже","добрый вечер","мне жаль"],"correctAnswer":"добрый вечер","explanation":"«good evening» — «добрый вечер»."},{"id":5,"question":"Какое выражение на британском английском соответствует «спасибо»?","options":["thank you","excuse me","hello","please"],"correctAnswer":"thank you","explanation":"«thank you» — «спасибо»."},{"id":6,"question":"Выбери точное русское значение выражения «I am sorry».","options":["извините","мне жаль","как дела?","добрый вечер"],"correctAnswer":"мне жаль","explanation":"«I am sorry» — «мне жаль»."},{"id":7,"question":"Выбери точное русское значение выражения «could you help me?».","options":["как дела?","привет","не могли бы вы мне помочь?","мне жаль"],"correctAnswer":"не могли бы вы мне помочь?","explanation":"«could you help me?» — «не могли бы вы мне помочь?»."},{"id":8,"question":"Какое выражение на британском английском соответствует «доброе утро»?","options":["good morning","thank you","nice to meet you","how are you?"],"correctAnswer":"good morning","explanation":"«good morning» — «доброе утро»."}],"durationMinutes":7,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 29 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000032,'challenges','{"id":760300000000032,"title":"A2 · Разговорный · Знакомство и этикет · Challenge 32","description":"A2: знакомство и этикет. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"A2","icon":"⚡","xp":31,"category":"Знакомство и этикет","track":"Разговорный","topic":"Знакомство и этикет","duration":"8 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «let me know».","options":["это зависит от обстоятельств","я согласен","я не согласен","дай мне знать"],"correctAnswer":"дай мне знать","explanation":"«let me know» — «дай мне знать»."},{"id":2,"question":"Какое выражение на британском английском соответствует «я не согласен»?","options":["it depends","I am looking for","I disagree","let me know"],"correctAnswer":"I disagree","explanation":"«I disagree» — «я не согласен»."},{"id":3,"question":"Выбери точное русское значение выражения «I am looking for».","options":["я согласен","я ищу","я бы хотел","что ты думаешь?"],"correctAnswer":"я ищу","explanation":"«I am looking for» — «я ищу»."},{"id":4,"question":"Выбери точное русское значение выражения «shall we start?».","options":["что ты думаешь?","начнём?","можно мне","я не уверен"],"correctAnswer":"начнём?","explanation":"«shall we start?» — «начнём?»."},{"id":5,"question":"Какое выражение на британском английском соответствует «я согласен»?","options":["could I have","it depends","I am looking for","I agree"],"correctAnswer":"I agree","explanation":"«I agree» — «я согласен»."},{"id":6,"question":"Выбери точное русское значение выражения «it depends».","options":["это зависит от обстоятельств","начнём?","кстати","я не уверен"],"correctAnswer":"это зависит от обстоятельств","explanation":"«it depends» — «это зависит от обстоятельств»."},{"id":7,"question":"Выбери точное русское значение выражения «I am not sure».","options":["я не уверен","я не согласен","я ищу","я согласен"],"correctAnswer":"я не уверен","explanation":"«I am not sure» — «я не уверен»."},{"id":8,"question":"Какое выражение на британском английском соответствует «я бы хотел»?","options":["I would like","I am not sure","what do you think?","I disagree"],"correctAnswer":"I would like","explanation":"«I would like» — «я бы хотел»."}],"durationMinutes":8,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 31 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000033,'challenges','{"id":760300000000033,"title":"B1 · Разговорный · Знакомство и этикет · Challenge 33","description":"B1: знакомство и этикет. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B1","icon":"⚡","xp":36,"category":"Знакомство и этикет","track":"Разговорный","topic":"Знакомство и этикет","duration":"9 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «reach an agreement».","options":["если честно","поддерживать связь","предложить идею","достичь соглашения"],"correctAnswer":"достичь соглашения","explanation":"«reach an agreement» — «достичь соглашения»."},{"id":2,"question":"Какое выражение на британском английском соответствует «прояснить недоразумение»?","options":["as far as I know","clear up a misunderstanding","to be honest","on the other hand"],"correctAnswer":"clear up a misunderstanding","explanation":"«clear up a misunderstanding» — «прояснить недоразумение»."},{"id":3,"question":"Выбери точное русское значение выражения «in my opinion».","options":["я понимаю твою точку зрения","насколько мне известно","предложить идею","по моему мнению"],"correctAnswer":"по моему мнению","explanation":"«in my opinion» — «по моему мнению»."},{"id":4,"question":"Выбери точное русское значение выражения «as far as I know».","options":["насколько мне известно","достичь соглашения","с другой стороны","предложить идею"],"correctAnswer":"насколько мне известно","explanation":"«as far as I know» — «насколько мне известно»."},{"id":5,"question":"Какое выражение на британском английском соответствует «предложить идею»?","options":["make a suggestion","to be honest","that sounds reasonable","clear up a misunderstanding"],"correctAnswer":"make a suggestion","explanation":"«make a suggestion» — «предложить идею»."},{"id":6,"question":"Выбери точное русское значение выражения «take part in».","options":["принимать участие в","я понимаю твою точку зрения","прояснить недоразумение","это звучит разумно"],"correctAnswer":"принимать участие в","explanation":"«take part in» — «принимать участие в»."},{"id":7,"question":"Выбери точное русское значение выражения «look forward to».","options":["с нетерпением ждать","с другой стороны","я понимаю твою точку зрения","достичь соглашения"],"correctAnswer":"с нетерпением ждать","explanation":"«look forward to» — «с нетерпением ждать»."},{"id":8,"question":"Какое выражение на британском английском соответствует «если честно»?","options":["clear up a misunderstanding","keep in touch","to be honest","take part in"],"correctAnswer":"to be honest","explanation":"«to be honest» — «если честно»."}],"durationMinutes":9,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 36 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000034,'challenges','{"id":760300000000034,"title":"B2 · Разговорный · Знакомство и этикет · Challenge 34","description":"B2: знакомство и этикет. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B2","icon":"⚡","xp":41,"category":"Знакомство и этикет","track":"Разговорный","topic":"Знакомство и этикет","duration":"10 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «make a valid point».","options":["прийти к выводу","привести веский аргумент","взвесить варианты","принять во внимание"],"correctAnswer":"привести веский аргумент","explanation":"«make a valid point» — «привести веский аргумент»."},{"id":2,"question":"Какое выражение на британском английском соответствует «выразить обеспокоенность»?","options":["weigh up the options","have mixed feelings","respond tactfully","raise a concern"],"correctAnswer":"raise a concern","explanation":"«raise a concern» — «выразить обеспокоенность»."},{"id":3,"question":"Выбери точное русское значение выражения «address a misunderstanding».","options":["прояснить предположение","разобраться с недопониманием","испытывать смешанные чувства","привести веский аргумент"],"correctAnswer":"разобраться с недопониманием","explanation":"«address a misunderstanding» — «разобраться с недопониманием»."},{"id":4,"question":"Выбери точное русское значение выражения «weigh up the options».","options":["найти баланс","прийти к выводу","привести веский аргумент","взвесить варианты"],"correctAnswer":"взвесить варианты","explanation":"«weigh up the options» — «взвесить варианты»."},{"id":5,"question":"Какое выражение на британском английском соответствует «выразить иначе»?","options":["put it another way","strike a balance","raise a concern","weigh up the options"],"correctAnswer":"put it another way","explanation":"«put it another way» — «выразить иначе»."},{"id":6,"question":"Выбери точное русское значение выражения «take into account».","options":["прийти к выводу","принять во внимание","выразить сомнение","взвесить варианты"],"correctAnswer":"принять во внимание","explanation":"«take into account» — «принять во внимание»."},{"id":7,"question":"Выбери точное русское значение выражения «strike a balance».","options":["найти баланс","привести веский аргумент","принять во внимание","взвесить варианты"],"correctAnswer":"найти баланс","explanation":"«strike a balance» — «найти баланс»."},{"id":8,"question":"Какое выражение на британском английском соответствует «прийти к выводу»?","options":["have mixed feelings","raise a concern","make a valid point","come to a conclusion"],"correctAnswer":"come to a conclusion","explanation":"«come to a conclusion» — «прийти к выводу»."}],"durationMinutes":10,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 41 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000035,'challenges','{"id":760300000000035,"title":"C1 · Разговорный · Знакомство и этикет · Challenge 35","description":"C1: знакомство и этикет. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"⚡","xp":46,"category":"Знакомство и этикет","track":"Разговорный","topic":"Знакомство и этикет","duration":"11 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «acknowledge a counterargument».","options":["уточнить оговорками утверждение","развернуть мысль","сформулировать вопрос нейтрально","признать контраргумент"],"correctAnswer":"признать контраргумент","explanation":"«acknowledge a counterargument» — «признать контраргумент»."},{"id":2,"question":"Какое выражение на британском английском соответствует «развернуть мысль»?","options":["build common ground","qualify a statement","acknowledge a counterargument","elaborate on a point"],"correctAnswer":"elaborate on a point","explanation":"«elaborate on a point» — «развернуть мысль»."},{"id":3,"question":"Выбери точное русское значение выражения «build common ground».","options":["развернуть мысль","уточнить оговорками утверждение","найти точки соприкосновения","подобрать стиль общения"],"correctAnswer":"найти точки соприкосновения","explanation":"«build common ground» — «найти точки соприкосновения»."},{"id":4,"question":"Выбери точное русское значение выражения «adapt the register».","options":["подобрать стиль общения","признать обоснованность довода","оспорить предположение","выражаться точно"],"correctAnswer":"подобрать стиль общения","explanation":"«adapt the register» — «подобрать стиль общения»."},{"id":5,"question":"Какое выражение на британском английском соответствует «выражаться точно»?","options":["challenge an assumption","draw an inference","frame a question neutrally","speak with precision"],"correctAnswer":"speak with precision","explanation":"«speak with precision» — «выражаться точно»."},{"id":6,"question":"Выбери точное русское значение выражения «frame a question neutrally».","options":["признать контраргумент","сформулировать вопрос нейтрально","передать тонкое различие","признать обоснованность довода"],"correctAnswer":"сформулировать вопрос нейтрально","explanation":"«frame a question neutrally» — «сформулировать вопрос нейтрально»."},{"id":7,"question":"Выбери точное русское значение выражения «qualify a statement».","options":["выражаться точно","уточнить оговорками утверждение","признать обоснованность довода","передать тонкое различие"],"correctAnswer":"уточнить оговорками утверждение","explanation":"«qualify a statement» — «уточнить оговорками утверждение»."},{"id":8,"question":"Какое выражение на британском английском соответствует «оспорить предположение»?","options":["concede a point","qualify a statement","challenge an assumption","convey a subtle distinction"],"correctAnswer":"challenge an assumption","explanation":"«challenge an assumption» — «оспорить предположение»."}],"durationMinutes":11,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 46 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000036,'challenges','{"id":760300000000036,"title":"C2 · Разговорный · Знакомство и этикет · Challenge 36","description":"C2: знакомство и этикет. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C2","icon":"⚡","xp":54,"category":"Знакомство и этикет","track":"Разговорный","topic":"Знакомство и этикет","duration":"12 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «reach a considered judgement».","options":["сформулировать оговорку","выдвинуть на первый план последствия","разграничить намерение и результат","прийти к взвешенному суждению"],"correctAnswer":"прийти к взвешенному суждению","explanation":"«reach a considered judgement» — «прийти к взвешенному суждению»."},{"id":2,"question":"Какое выражение на британском английском соответствует «выдвинуть на первый план последствия»?","options":["invite a qualified response","expose a false dichotomy","foreground the implications","reach a considered judgement"],"correctAnswer":"foreground the implications","explanation":"«foreground the implications» — «выдвинуть на первый план последствия»."},{"id":3,"question":"Выбери точное русское значение выражения «distinguish intent from impact».","options":["прийти к взвешенному суждению","согласовать разные точки зрения","оспорить исходную предпосылку","разграничить намерение и результат"],"correctAnswer":"разграничить намерение и результат","explanation":"«distinguish intent from impact» — «разграничить намерение и результат»."},{"id":4,"question":"Выбери точное русское значение выражения «expose a false dichotomy».","options":["сформулировать оговорку","прийти к взвешенному суждению","синтезировать противоположные взгляды","выявить ложную дихотомию"],"correctAnswer":"выявить ложную дихотомию","explanation":"«expose a false dichotomy» — «выявить ложную дихотомию»."},{"id":5,"question":"Какое выражение на британском английском соответствует «синтезировать противоположные взгляды»?","options":["maintain rhetorical restraint","avoid unwarranted certainty","articulate a caveat","synthesise opposing views"],"correctAnswer":"synthesise opposing views","explanation":"«synthesise opposing views» — «синтезировать противоположные взгляды»."},{"id":6,"question":"Выбери точное русское значение выражения «articulate a caveat».","options":["выявить ложную дихотомию","синтезировать противоположные взгляды","сформулировать оговорку","предложить ответ с оговорками"],"correctAnswer":"сформулировать оговорку","explanation":"«articulate a caveat» — «сформулировать оговорку»."},{"id":7,"question":"Выбери точное русское значение выражения «make a nuanced distinction».","options":["провести тонкое различие","прийти к взвешенному суждению","разграничить намерение и результат","согласовать разные точки зрения"],"correctAnswer":"провести тонкое различие","explanation":"«make a nuanced distinction» — «провести тонкое различие»."},{"id":8,"question":"Какое выражение на британском английском соответствует «избегать необоснованной уверенности»?","options":["maintain rhetorical restraint","avoid unwarranted certainty","expose a false dichotomy","articulate a caveat"],"correctAnswer":"avoid unwarranted certainty","explanation":"«avoid unwarranted certainty» — «избегать необоснованной уверенности»."}],"durationMinutes":12,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 54 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000037,'challenges','{"id":760300000000037,"title":"A1 · Разговорный · Повседневные ситуации · Challenge 37","description":"A1: повседневные ситуации. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"A1","icon":"⚡","xp":26,"category":"Повседневные ситуации","track":"Разговорный","topic":"Повседневные ситуации","duration":"7 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «please».","options":["пожалуйста","увидимся позже","приятно познакомиться","извините"],"correctAnswer":"пожалуйста","explanation":"«please» — «пожалуйста»."},{"id":2,"question":"Какое выражение на британском английском соответствует «приятно познакомиться»?","options":["please","nice to meet you","excuse me","could you help me?"],"correctAnswer":"nice to meet you","explanation":"«nice to meet you» — «приятно познакомиться»."},{"id":3,"question":"Выбери точное русское значение выражения «excuse me».","options":["извините","приятно познакомиться","спасибо","как дела?"],"correctAnswer":"извините","explanation":"«excuse me» — «извините»."},{"id":4,"question":"Выбери точное русское значение выражения «I am sorry».","options":["не могли бы вы мне помочь?","пожалуйста","как дела?","мне жаль"],"correctAnswer":"мне жаль","explanation":"«I am sorry» — «мне жаль»."},{"id":5,"question":"Какое выражение на британском английском соответствует «спасибо»?","options":["excuse me","my name is","could you help me?","thank you"],"correctAnswer":"thank you","explanation":"«thank you» — «спасибо»."},{"id":6,"question":"Выбери точное русское значение выражения «how are you?».","options":["добрый вечер","мне жаль","привет","как дела?"],"correctAnswer":"как дела?","explanation":"«how are you?» — «как дела?»."},{"id":7,"question":"Выбери точное русское значение выражения «good evening».","options":["мне жаль","извините","доброе утро","добрый вечер"],"correctAnswer":"добрый вечер","explanation":"«good evening» — «добрый вечер»."},{"id":8,"question":"Какое выражение на британском английском соответствует «увидимся позже»?","options":["my name is","nice to meet you","see you later","I am sorry"],"correctAnswer":"see you later","explanation":"«see you later» — «увидимся позже»."}],"durationMinutes":7,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 26 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000038,'challenges','{"id":760300000000038,"title":"A2 · Разговорный · Повседневные ситуации · Challenge 38","description":"A2: повседневные ситуации. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"A2","icon":"⚡","xp":31,"category":"Повседневные ситуации","track":"Разговорный","topic":"Повседневные ситуации","duration":"8 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «by the way».","options":["я ищу","я не согласен","кстати","что ты думаешь?"],"correctAnswer":"кстати","explanation":"«by the way» — «кстати»."},{"id":2,"question":"Какое выражение на британском английском соответствует «не торопись»?","options":["I disagree","let me know","take your time","it depends"],"correctAnswer":"take your time","explanation":"«take your time» — «не торопись»."},{"id":3,"question":"Выбери точное русское значение выражения «I am looking for».","options":["я ищу","я не согласен","я бы хотел","я не уверен"],"correctAnswer":"я ищу","explanation":"«I am looking for» — «я ищу»."},{"id":4,"question":"Выбери точное русское значение выражения «I agree».","options":["я бы хотел","дай мне знать","это зависит от обстоятельств","я согласен"],"correctAnswer":"я согласен","explanation":"«I agree» — «я согласен»."},{"id":5,"question":"Какое выражение на британском английском соответствует «я бы хотел»?","options":["let me know","could I have","I would like","I agree"],"correctAnswer":"I would like","explanation":"«I would like» — «я бы хотел»."},{"id":6,"question":"Выбери точное русское значение выражения «could I have».","options":["можно мне","я ищу","дай мне знать","кстати"],"correctAnswer":"можно мне","explanation":"«could I have» — «можно мне»."},{"id":7,"question":"Выбери точное русское значение выражения «I am not sure».","options":["я не уверен","я бы хотел","можно мне","что ты думаешь?"],"correctAnswer":"я не уверен","explanation":"«I am not sure» — «я не уверен»."},{"id":8,"question":"Какое выражение на британском английском соответствует «начнём?»?","options":["let me know","I am looking for","shall we start?","could I have"],"correctAnswer":"shall we start?","explanation":"«shall we start?» — «начнём?»."}],"durationMinutes":8,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 31 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000039,'challenges','{"id":760300000000039,"title":"B1 · Разговорный · Повседневные ситуации · Challenge 39","description":"B1: повседневные ситуации. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B1","icon":"⚡","xp":36,"category":"Повседневные ситуации","track":"Разговорный","topic":"Повседневные ситуации","duration":"9 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «take part in».","options":["принимать участие в","предложить идею","я понимаю твою точку зрения","если честно"],"correctAnswer":"принимать участие в","explanation":"«take part in» — «принимать участие в»."},{"id":2,"question":"Какое выражение на британском английском соответствует «я понимаю твою точку зрения»?","options":["look forward to","clear up a misunderstanding","keep in touch","I see your point"],"correctAnswer":"I see your point","explanation":"«I see your point» — «я понимаю твою точку зрения»."},{"id":3,"question":"Выбери точное русское значение выражения «reach an agreement».","options":["по моему мнению","достичь соглашения","принимать участие в","предложить идею"],"correctAnswer":"достичь соглашения","explanation":"«reach an agreement» — «достичь соглашения»."},{"id":4,"question":"Выбери точное русское значение выражения «as far as I know».","options":["прояснить недоразумение","принимать участие в","по моему мнению","насколько мне известно"],"correctAnswer":"насколько мне известно","explanation":"«as far as I know» — «насколько мне известно»."},{"id":5,"question":"Какое выражение на британском английском соответствует «если честно»?","options":["in my opinion","that sounds reasonable","reach an agreement","to be honest"],"correctAnswer":"to be honest","explanation":"«to be honest» — «если честно»."},{"id":6,"question":"Выбери точное русское значение выражения «look forward to».","options":["если честно","с нетерпением ждать","насколько мне известно","с другой стороны"],"correctAnswer":"с нетерпением ждать","explanation":"«look forward to» — «с нетерпением ждать»."},{"id":7,"question":"Выбери точное русское значение выражения «in my opinion».","options":["я понимаю твою точку зрения","с другой стороны","по моему мнению","с нетерпением ждать"],"correctAnswer":"по моему мнению","explanation":"«in my opinion» — «по моему мнению»."},{"id":8,"question":"Какое выражение на британском английском соответствует «предложить идею»?","options":["to be honest","make a suggestion","on the other hand","as far as I know"],"correctAnswer":"make a suggestion","explanation":"«make a suggestion» — «предложить идею»."}],"durationMinutes":9,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 36 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000040,'challenges','{"id":760300000000040,"title":"B2 · Разговорный · Повседневные ситуации · Challenge 40","description":"B2: повседневные ситуации. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B2","icon":"⚡","xp":41,"category":"Повседневные ситуации","track":"Разговорный","topic":"Повседневные ситуации","duration":"10 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «have mixed feelings».","options":["испытывать смешанные чувства","выразить обеспокоенность","принять во внимание","найти баланс"],"correctAnswer":"испытывать смешанные чувства","explanation":"«have mixed feelings» — «испытывать смешанные чувства»."},{"id":2,"question":"Какое выражение на британском английском соответствует «принять во внимание»?","options":["put it another way","address a misunderstanding","have mixed feelings","take into account"],"correctAnswer":"take into account","explanation":"«take into account» — «принять во внимание»."},{"id":3,"question":"Выбери точное русское значение выражения «express a reservation».","options":["взвесить варианты","прояснить предположение","разобраться с недопониманием","выразить сомнение"],"correctAnswer":"выразить сомнение","explanation":"«express a reservation» — «выразить сомнение»."},{"id":4,"question":"Выбери точное русское значение выражения «make a valid point».","options":["привести веский аргумент","выразить иначе","найти баланс","выразить сомнение"],"correctAnswer":"привести веский аргумент","explanation":"«make a valid point» — «привести веский аргумент»."},{"id":5,"question":"Какое выражение на британском английском соответствует «ответить тактично»?","options":["clarify an assumption","weigh up the options","take into account","respond tactfully"],"correctAnswer":"respond tactfully","explanation":"«respond tactfully» — «ответить тактично»."},{"id":6,"question":"Выбери точное русское значение выражения «weigh up the options».","options":["взвесить варианты","выразить сомнение","испытывать смешанные чувства","прояснить предположение"],"correctAnswer":"взвесить варианты","explanation":"«weigh up the options» — «взвесить варианты»."},{"id":7,"question":"Выбери точное русское значение выражения «clarify an assumption».","options":["принять во внимание","прояснить предположение","испытывать смешанные чувства","выразить обеспокоенность"],"correctAnswer":"прояснить предположение","explanation":"«clarify an assumption» — «прояснить предположение»."},{"id":8,"question":"Какое выражение на британском английском соответствует «разобраться с недопониманием»?","options":["address a misunderstanding","put it another way","raise a concern","respond tactfully"],"correctAnswer":"address a misunderstanding","explanation":"«address a misunderstanding» — «разобраться с недопониманием»."}],"durationMinutes":10,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 41 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000041,'challenges','{"id":760300000000041,"title":"C1 · Разговорный · Повседневные ситуации · Challenge 41","description":"C1: повседневные ситуации. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"⚡","xp":49,"category":"Повседневные ситуации","track":"Разговорный","topic":"Повседневные ситуации","duration":"11 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «draw an inference».","options":["найти точки соприкосновения","признать обоснованность довода","модерировать обсуждение","сделать вывод"],"correctAnswer":"сделать вывод","explanation":"«draw an inference» — «сделать вывод»."},{"id":2,"question":"Какое выражение на британском английском соответствует «сформулировать вопрос нейтрально»?","options":["concede a point","challenge an assumption","frame a question neutrally","elaborate on a point"],"correctAnswer":"frame a question neutrally","explanation":"«frame a question neutrally» — «сформулировать вопрос нейтрально»."},{"id":3,"question":"Выбери точное русское значение выражения «qualify a statement».","options":["признать контраргумент","модерировать обсуждение","уточнить оговорками утверждение","развернуть мысль"],"correctAnswer":"уточнить оговорками утверждение","explanation":"«qualify a statement» — «уточнить оговорками утверждение»."},{"id":4,"question":"Выбери точное русское значение выражения «acknowledge a counterargument».","options":["сформулировать вопрос нейтрально","признать контраргумент","признать обоснованность довода","найти точки соприкосновения"],"correctAnswer":"признать контраргумент","explanation":"«acknowledge a counterargument» — «признать контраргумент»."},{"id":5,"question":"Какое выражение на британском английском соответствует «развернуть мысль»?","options":["build common ground","frame a question neutrally","adapt the register","elaborate on a point"],"correctAnswer":"elaborate on a point","explanation":"«elaborate on a point» — «развернуть мысль»."},{"id":6,"question":"Выбери точное русское значение выражения «moderate a discussion».","options":["признать контраргумент","модерировать обсуждение","сделать вывод","найти точки соприкосновения"],"correctAnswer":"модерировать обсуждение","explanation":"«moderate a discussion» — «модерировать обсуждение»."},{"id":7,"question":"Выбери точное русское значение выражения «adapt the register».","options":["признать обоснованность довода","сформулировать вопрос нейтрально","признать контраргумент","подобрать стиль общения"],"correctAnswer":"подобрать стиль общения","explanation":"«adapt the register» — «подобрать стиль общения»."},{"id":8,"question":"Какое выражение на британском английском соответствует «оспорить предположение»?","options":["qualify a statement","challenge an assumption","convey a subtle distinction","concede a point"],"correctAnswer":"challenge an assumption","explanation":"«challenge an assumption» — «оспорить предположение»."}],"durationMinutes":11,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 49 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000042,'challenges','{"id":760300000000042,"title":"C2 · Разговорный · Повседневные ситуации · Challenge 42","description":"C2: повседневные ситуации. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C2","icon":"⚡","xp":51,"category":"Повседневные ситуации","track":"Разговорный","topic":"Повседневные ситуации","duration":"12 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «articulate a caveat».","options":["сформулировать оговорку","провести тонкое различие","синтезировать противоположные взгляды","выдвинуть на первый план последствия"],"correctAnswer":"сформулировать оговорку","explanation":"«articulate a caveat» — «сформулировать оговорку»."},{"id":2,"question":"Какое выражение на британском английском соответствует «согласовать разные точки зрения»?","options":["avoid unwarranted certainty","reconcile competing perspectives","make a nuanced distinction","foreground the implications"],"correctAnswer":"reconcile competing perspectives","explanation":"«reconcile competing perspectives» — «согласовать разные точки зрения»."},{"id":3,"question":"Выбери точное русское значение выражения «expose a false dichotomy».","options":["избегать необоснованной уверенности","выявить ложную дихотомию","сохранять риторическую сдержанность","согласовать разные точки зрения"],"correctAnswer":"выявить ложную дихотомию","explanation":"«expose a false dichotomy» — «выявить ложную дихотомию»."},{"id":4,"question":"Выбери точное русское значение выражения «maintain rhetorical restraint».","options":["сформулировать оговорку","избегать необоснованной уверенности","согласовать разные точки зрения","сохранять риторическую сдержанность"],"correctAnswer":"сохранять риторическую сдержанность","explanation":"«maintain rhetorical restraint» — «сохранять риторическую сдержанность»."},{"id":5,"question":"Какое выражение на британском английском соответствует «разграничить намерение и результат»?","options":["invite a qualified response","reconcile competing perspectives","distinguish intent from impact","synthesise opposing views"],"correctAnswer":"distinguish intent from impact","explanation":"«distinguish intent from impact» — «разграничить намерение и результат»."},{"id":6,"question":"Выбери точное русское значение выражения «reach a considered judgement».","options":["избегать необоснованной уверенности","синтезировать противоположные взгляды","прийти к взвешенному суждению","предложить ответ с оговорками"],"correctAnswer":"прийти к взвешенному суждению","explanation":"«reach a considered judgement» — «прийти к взвешенному суждению»."},{"id":7,"question":"Выбери точное русское значение выражения «synthesise opposing views».","options":["выявить ложную дихотомию","согласовать разные точки зрения","синтезировать противоположные взгляды","сохранять риторическую сдержанность"],"correctAnswer":"синтезировать противоположные взгляды","explanation":"«synthesise opposing views» — «синтезировать противоположные взгляды»."},{"id":8,"question":"Какое выражение на британском английском соответствует «предложить ответ с оговорками»?","options":["invite a qualified response","maintain rhetorical restraint","make a nuanced distinction","avoid unwarranted certainty"],"correctAnswer":"invite a qualified response","explanation":"«invite a qualified response» — «предложить ответ с оговорками»."}],"durationMinutes":12,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 51 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
