r":"мне жаль","explanation":"«I am sorry» — «мне жаль»."},{"id":8,"question":"Какое выражение на британском английском соответствует «спасибо»?","options":["my name is","nice to meet you","see you later","thank you"],"correctAnswer":"thank you","explanation":"«thank you» — «спасибо»."}],"durationMinutes":7,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 26 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000044,'challenges','{"id":760300000000044,"title":"A2 · Разговорный · Мнение и общение · Challenge 44","description":"A2: мнение и общение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"A2","icon":"⚡","xp":31,"category":"Мнение и общение","track":"Разговорный","topic":"Мнение и общение","duration":"8 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «could I have».","options":["что ты думаешь?","не торопись","можно мне","это зависит от обстоятельств"],"correctAnswer":"можно мне","explanation":"«could I have» — «можно мне»."},{"id":2,"question":"Какое выражение на британском английском соответствует «я бы хотел»?","options":["I am not sure","I would like","could I have","it depends"],"correctAnswer":"I would like","explanation":"«I would like» — «я бы хотел»."},{"id":3,"question":"Выбери точное русское значение выражения «it depends».","options":["что ты думаешь?","я согласен","это зависит от обстоятельств","не торопись"],"correctAnswer":"это зависит от обстоятельств","explanation":"«it depends» — «это зависит от обстоятельств»."},{"id":4,"question":"Выбери точное русское значение выражения «I am not sure».","options":["не торопись","я не уверен","можно мне","я ищу"],"correctAnswer":"я не уверен","explanation":"«I am not sure» — «я не уверен»."},{"id":5,"question":"Какое выражение на британском английском соответствует «я ищу»?","options":["what do you think?","I am looking for","could I have","I agree"],"correctAnswer":"I am looking for","explanation":"«I am looking for» — «я ищу»."},{"id":6,"question":"Выбери точное русское значение выражения «I agree».","options":["кстати","я ищу","это зависит от обстоятельств","я согласен"],"correctAnswer":"я согласен","explanation":"«I agree» — «я согласен»."},{"id":7,"question":"Выбери точное русское значение выражения «let me know».","options":["начнём?","дай мне знать","я бы хотел","я не согласен"],"correctAnswer":"дай мне знать","explanation":"«let me know» — «дай мне знать»."},{"id":8,"question":"Какое выражение на британском английском соответствует «начнём?»?","options":["shall we start?","I would like","I am not sure","I disagree"],"correctAnswer":"shall we start?","explanation":"«shall we start?» — «начнём?»."}],"durationMinutes":8,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 31 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000045,'challenges','{"id":760300000000045,"title":"B1 · Разговорный · Мнение и общение · Challenge 45","description":"B1: мнение и общение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B1","icon":"⚡","xp":36,"category":"Мнение и общение","track":"Разговорный","topic":"Мнение и общение","duration":"9 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «on the other hand».","options":["с другой стороны","по моему мнению","предложить идею","прояснить недоразумение"],"correctAnswer":"с другой стороны","explanation":"«on the other hand» — «с другой стороны»."},{"id":2,"question":"Какое выражение на британском английском соответствует «насколько мне известно»?","options":["as far as I know","keep in touch","look forward to","on the other hand"],"correctAnswer":"as far as I know","explanation":"«as far as I know» — «насколько мне известно»."},{"id":3,"question":"Выбери точное русское значение выражения «to be honest».","options":["прояснить недоразумение","принимать участие в","если честно","с другой стороны"],"correctAnswer":"если честно","explanation":"«to be honest» — «если честно»."},{"id":4,"question":"Выбери точное русское значение выражения «I see your point».","options":["я понимаю твою точку зрения","принимать участие в","достичь соглашения","предложить идею"],"correctAnswer":"я понимаю твою точку зрения","explanation":"«I see your point» — «я понимаю твою точку зрения»."},{"id":5,"question":"Какое выражение на британском английском соответствует «прояснить недоразумение»?","options":["that sounds reasonable","clear up a misunderstanding","keep in touch","reach an agreement"],"correctAnswer":"clear up a misunderstanding","explanation":"«clear up a misunderstanding» — «прояснить недоразумение»."},{"id":6,"question":"Выбери точное русское значение выражения «take part in».","options":["принимать участие в","с другой стороны","если честно","предложить идею"],"correctAnswer":"принимать участие в","explanation":"«take part in» — «принимать участие в»."},{"id":7,"question":"Выбери точное русское значение выражения «reach an agreement».","options":["если честно","я понимаю твою точку зрения","прояснить недоразумение","достичь соглашения"],"correctAnswer":"достичь соглашения","explanation":"«reach an agreement» — «достичь соглашения»."},{"id":8,"question":"Какое выражение на британском английском соответствует «предложить идею»?","options":["that sounds reasonable","look forward to","as far as I know","make a suggestion"],"correctAnswer":"make a suggestion","explanation":"«make a suggestion» — «предложить идею»."}],"durationMinutes":9,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 36 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000046,'challenges','{"id":760300000000046,"title":"B2 · Разговорный · Мнение и общение · Challenge 46","description":"B2: мнение и общение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B2","icon":"⚡","xp":44,"category":"Мнение и общение","track":"Разговорный","topic":"Мнение и общение","duration":"10 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «take into account».","options":["разобраться с недопониманием","найти баланс","выразить сомнение","принять во внимание"],"correctAnswer":"принять во внимание","explanation":"«take into account» — «принять во внимание»."},{"id":2,"question":"Какое выражение на британском английском соответствует «прояснить предположение»?","options":["come to a conclusion","clarify an assumption","have mixed feelings","respond tactfully"],"correctAnswer":"clarify an assumption","explanation":"«clarify an assumption» — «прояснить предположение»."},{"id":3,"question":"Выбери точное русское значение выражения «put it another way».","options":["прояснить предположение","выразить иначе","привести веский аргумент","испытывать смешанные чувства"],"correctAnswer":"выразить иначе","explanation":"«put it another way» — «выразить иначе»."},{"id":4,"question":"Выбери точное русское значение выражения «have mixed feelings».","options":["выразить сомнение","испытывать смешанные чувства","взвесить варианты","привести веский аргумент"],"correctAnswer":"испытывать смешанные чувства","explanation":"«have mixed feelings» — «испытывать смешанные чувства»."},{"id":5,"question":"Какое выражение на британском английском соответствует «выразить обеспокоенность»?","options":["raise a concern","clarify an assumption","take into account","address a misunderstanding"],"correctAnswer":"raise a concern","explanation":"«raise a concern» — «выразить обеспокоенность»."},{"id":6,"question":"Выбери точное русское значение выражения «make a valid point».","options":["привести веский аргумент","прийти к выводу","ответить тактично","выразить обеспокоенность"],"correctAnswer":"привести веский аргумент","explanation":"«make a valid point» — «привести веский аргумент»."},{"id":7,"question":"Выбери точное русское значение выражения «address a misunderstanding».","options":["испытывать смешанные чувства","прийти к выводу","привести веский аргумент","разобраться с недопониманием"],"correctAnswer":"разобраться с недопониманием","explanation":"«address a misunderstanding» — «разобраться с недопониманием»."},{"id":8,"question":"Какое выражение на британском английском соответствует «прийти к выводу»?","options":["take into account","strike a balance","have mixed feelings","come to a conclusion"],"correctAnswer":"come to a conclusion","explanation":"«come to a conclusion» — «прийти к выводу»."}],"durationMinutes":10,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 44 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000047,'challenges','{"id":760300000000047,"title":"C1 · Разговорный · Мнение и общение · Challenge 47","description":"C1: мнение и общение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"⚡","xp":46,"category":"Мнение и общение","track":"Разговорный","topic":"Мнение и общение","duration":"11 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «acknowledge a counterargument».","options":["развернуть мысль","признать контраргумент","признать обоснованность довода","сделать вывод"],"correctAnswer":"признать контраргумент","explanation":"«acknowledge a counterargument» — «признать контраргумент»."},{"id":2,"question":"Какое выражение на британском английском соответствует «уточнить оговорками утверждение»?","options":["convey a subtle distinction","qualify a statement","adapt the register","moderate a discussion"],"correctAnswer":"qualify a statement","explanation":"«qualify a statement» — «уточнить оговорками утверждение»."},{"id":3,"question":"Выбери точное русское значение выражения «elaborate on a point».","options":["развернуть мысль","найти точки соприкосновения","сделать вывод","признать контраргумент"],"correctAnswer":"развернуть мысль","explanation":"«elaborate on a point» — «развернуть мысль»."},{"id":4,"question":"Выбери точное русское значение выражения «build common ground».","options":["сделать вывод","оспорить предположение","признать контраргумент","найти точки соприкосновения"],"correctAnswer":"найти точки соприкосновения","explanation":"«build common ground» — «найти точки соприкосновения»."},{"id":5,"question":"Какое выражение на британском английском соответствует «подобрать стиль общения»?","options":["moderate a discussion","concede a point","adapt the register","build common ground"],"correctAnswer":"adapt the register","explanation":"«adapt the register» — «подобрать стиль общения»."},{"id":6,"question":"Выбери точное русское значение выражения «draw an inference».","options":["признать обоснованность довода","уточнить оговорками утверждение","передать тонкое различие","сделать вывод"],"correctAnswer":"сделать вывод","explanation":"«draw an inference» — «сделать вывод»."},{"id":7,"question":"Выбери точное русское значение выражения «frame a question neutrally».","options":["передать тонкое различие","сформулировать вопрос нейтрально","найти точки соприкосновения","признать обоснованность довода"],"correctAnswer":"сформулировать вопрос нейтрально","explanation":"«frame a question neutrally» — «сформулировать вопрос нейтрально»."},{"id":8,"question":"Какое выражение на британском английском соответствует «передать тонкое различие»?","options":["speak with precision","qualify a statement","challenge an assumption","convey a subtle distinction"],"correctAnswer":"convey a subtle distinction","explanation":"«convey a subtle distinction» — «передать тонкое различие»."}],"durationMinutes":11,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 46 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760300000000048,'challenges','{"id":760300000000048,"title":"C2 · Разговорный · Мнение и общение · Challenge 48","description":"C2: мнение и общение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C2","icon":"⚡","xp":51,"category":"Мнение и общение","track":"Разговорный","topic":"Мнение и общение","duration":"12 мин","section":"challenges","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «invite a qualified response».","options":["предложить ответ с оговорками","согласовать разные точки зрения","оспорить исходную предпосылку","избегать необоснованной уверенности"],"correctAnswer":"предложить ответ с оговорками","explanation":"«invite a qualified response» — «предложить ответ с оговорками»."},{"id":2,"question":"Какое выражение на британском английском соответствует «согласовать разные точки зрения»?","options":["maintain rhetorical restraint","expose a false dichotomy","reconcile competing perspectives","foreground the implications"],"correctAnswer":"reconcile competing perspectives","explanation":"«reconcile competing perspectives» — «согласовать разные точки зрения»."},{"id":3,"question":"Выбери точное русское значение выражения «challenge the underlying premise».","options":["синтезировать противоположные взгляды","оспорить исходную предпосылку","прийти к взвешенному суждению","выявить ложную дихотомию"],"correctAnswer":"оспорить исходную предпосылку","explanation":"«challenge the underlying premise» — «оспорить исходную предпосылку»."},{"id":4,"question":"Выбери точное русское значение выражения «avoid unwarranted certainty».","options":["прийти к взвешенному суждению","сформулировать оговорку","разграничить намерение и результат","избегать необоснованной уверенности"],"correctAnswer":"избегать необоснованной уверенности","explanation":"«avoid unwarranted certainty» — «избегать необоснованной уверенности»."},{"id":5,"question":"Какое выражение на британском английском соответствует «сформулировать оговорку»?","options":["avoid unwarranted certainty","articulate a caveat","reach a considered judgement","distinguish intent from impact"],"correctAnswer":"articulate a caveat","explanation":"«articulate a caveat» — «сформулировать оговорку»."},{"id":6,"question":"Выбери точное русское значение выражения «synthesise opposing views».","options":["сохранять риторическую сдержанность","оспорить исходную предпосылку","синтезировать противоположные взгляды","сформулировать оговорку"],"correctAnswer":"синтезировать противоположные взгляды","explanation":"«synthesise opposing views» — «синтезировать противоположные взгляды»."},{"id":7,"question":"Выбери точное русское значение выражения «maintain rhetorical restraint».","options":["предложить ответ с оговорками","синтезировать противоположные взгляды","сохранять риторическую сдержанность","разграничить намерение и результат"],"correctAnswer":"сохранять риторическую сдержанность","explanation":"«maintain rhetorical restraint» — «сохранять риторическую сдержанность»."},{"id":8,"question":"Какое выражение на британском английском соответствует «разграничить намерение и результат»?","options":["distinguish intent from impact","articulate a caveat","reconcile competing perspectives","synthesise opposing views"],"correctAnswer":"distinguish intent from impact","explanation":"«distinguish intent from impact» — «разграничить намерение и результат»."}],"durationMinutes":12,"goal":"Ответь на 8 вопросов и сравни результат.","instructions":"За каждый правильный ответ начисляется пропорциональная часть XP после проверки сервера.","reward":"До 51 XP"}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
